    assert "\u25bc" not in pmv_mod.PLACEHOLDER_PACK, "PLACEHOLDER_PACK no debe contener el glifo ▼"
    assert "▼" not in pmv_mod.PLACEHOLDER_PACK, "PLACEHOLDER_PACK no debe contener el caracter de flecha ▼"
