class _NotisFalso_:
    def __init__(self):
        self.eventos = []

    def notify_pack_activated(self, *a):
        self.eventos.append(("kill",) + a)

    def notify_apps_launched(self, *a):
        self.eventos.append(("start",) + a)


class _HilosSincronos:
    """Ejecuta el cuerpo del worker EN EL HILO PRINCIPAL, sin crear un hilo.

    Por que hace falta: las puertas de las vistas arrancan un
    `threading.Thread(daemon=True)` real. En un test eso es una carrera: el
    assert puede correr antes de que el worker haga nada, y el fallo seria
    INTERMITENTE, que es peor que no tener test. Este contexto sustituye `Thread`
    por uno que ejecuta el target en el acto; es el mismo truco que el arnés ya
    usa con `after` en los tests de UI headless.
    """

    def __enter__(self):
        import woptimizer.ui.views.dashboard_view as mod
        import woptimizer.ui.views.pack_manager_view as mod_gestor
        self._mods = (mod, mod_gestor)
        self._reales = (mod.threading.Thread, mod_gestor.threading.Thread)
        self.hilos = []
        _yo = self

        class _T:
            def __init__(self, target=None, args=(), daemon=None):
                self._target = target
                self._args = args
                _yo.hilos.append(self)

            def start(self):
                self._target(*self._args)

            def join(self, timeout=None):
                return None

        for m in self._mods:
            m.threading.Thread = _T
        return self

    def __exit__(self, *exc):
        for m, real in zip(self._mods, self._reales):
            m.threading.Thread = real
        return False


def _orden_de_categoria(cat):
    from woptimizer.config import CATEGORY_ORDER
    return CATEGORY_ORDER.index(cat) if cat in CATEGORY_ORDER else 999


def test_pack_no_gaming_apaga_por_categoria_y_respeta_keepers():
    """#1. Un pack NORMAL con 0 apps y una categoria marcada apaga esa categoria.

    Por que discrimina: antes la ruta de apagado de un pack no gaming era
    `process_service.kill_pack_apps(p.apps)`, y con `apps=[]` devolvia
    `0,0,0,0.0` sin mirar NINGUNA linea de `target_categories`. Aqui el proceso
    de la categoria marcada tiene que LLEGAR a `kill_processes`, y el keeper
    seguir vivo aunque su categoria este marcada.
    """
    print("Testing pack no gaming apaga por categoria y respeta keepers...")
    from woptimizer.services.gaming_service import GamingService

    pack_s, tmp_path = _pack_service_temporal()
    try:
        spy = _ProcessServiceSpy()
        spy.snapshot = [
            ProcessInfo(name="onedrive", full_name="onedrive.exe", pid=2001,
                        category=_CAT_SYNC),
            ProcessInfo(name="discord", full_name="discord.exe", pid=2002,
                        category=_CAT_CHAT),
            ProcessInfo(name="woptimizer_zzz", full_name="woptimizer_zzz.exe",
                        pid=2003, category="\u26aa Otros"),
        ]
        gs = GamingService(spy, pack_s)
        pack = Pack(
            id="trabajo", name="Trabajo", default_action="kill",
            apps=[], keepers=["discord.exe"],
            target_categories=[_CAT_SYNC, _CAT_CHAT],
        )
        resultado = gs.execute_pack(pack)
        assert spy.capturados is not None, "execute_pack no llego a la via de kill"
        nombres = sorted(p.full_name for p in spy.capturados)
        assert nombres == ["onedrive.exe"], (
            "solo onedrive debe morir (categoria marcada); el keeper y el ajeno no. "
            f"Llegaron: {nombres}"
        )
        assert "discord.exe" not in nombres, (
            "el keeper gana aunque su categoria este marcada"
        )
        killed, failed, skipped, freed_mb = resultado
        assert (killed, failed) == (2, 0), (
            f"la tupla debe venir del doble sin alterar: {resultado}"
        )
        assert skipped == 0, f"nada hay que saltarse: {skipped}"
    finally:
        os.unlink(tmp_path)
    print("Pack no gaming apaga por categoria OK (TASK-063).")


def test_pack_con_categorias_supera_las_cuatro_guardas():
    """#2. El pack del #1 pasa las CUATRO guardas, en las DOS vistas.

    Por que discrimina: las dos guardas de apagado cortaban con "no tiene apps
    que apagar" ANTES de armar la confirmacion. Aqui la unica salida de la puerta
    tiene que ser la confirmacion, no el aviso.
    """
    print("Testing pack con categorias supera las cuatro guardas...")
    from woptimizer.ui.views.dashboard_view import DashboardView
    from woptimizer.ui.views.pack_manager_view import PackManagerView

    pack = Pack(id="trabajo", name="Trabajo", default_action="kill", apps=[],
               target_categories=[_CAT_SYNC])

    # Guarda #1: la del Gestor, que vive en `_aviso_pack_inerte`.
    v = PackManagerView.__new__(PackManagerView)
    aviso = v._aviso_pack_inerte(pack)
    assert aviso is None, (
        f"un pack con categorias marcadas tiene algo que apagar; el aviso "
        f"{aviso!r} miente sobre lo que la puerta va a hacer"
    )

    # Guardas #3 y #4: las de ARRIQUE del pack. Un pack que solo tiene
    # `target_categories` SI tiene algo que apagar y NADA que arrancar, asi que
    # la puerta de arrancar debe avisar y la de apagar no.
    d = DashboardView.__new__(DashboardView)
    vistos = []
    tocadas = []
    d._show_aviso_banner = lambda texto, color: vistos.append(texto)
    d._cancel_confirm = lambda: None
    d._require_double_tap = lambda token, button, aviso: (tocadas.append(aviso), True)[1]
    d._inline_status = lambda *a: None
    d.gaming_service = _GestorDePuertasFalso_()
    d.process_service = None
    d.notification_service = _NotisFalso_()
    d.status_label = _EtiquetaFalsa_()
    d.after = lambda ms, func=None, *a: None
    d._show_banner = lambda *a: None
    d._show_start_banner = lambda *a: None
    d._refrescar_banner = lambda: None
    with _HilosSincronos():
        d.execute_pack(pack)
    assert not vistos, (
        f"la guarda de la Portada corto con {vistos!r}: el pack tiene categorias "
        "marcadas y la puerta comun las apagaria"
    )
    assert tocadas, "la doble pulsacion no llego a armarse: la guarda corto antes"
    assert "apagar 0 apps" not in tocadas[0], (
        f"el texto sigue contando apps en vez de la puerta: {tocadas[0]!r}"
    )

    # Y el gemelo del Gestor, por su via real (`kill_pack`), que es donde vive
    # la doble pulsacion del pack.
    procs_vistos = []
    gestor = PackManagerView.__new__(PackManagerView)
    gestor.pack_service = _PackServiceFalso_({"trabajo": pack})
    gestor.gaming_service = _GestorDePuertasFalso_()
    gestor.notification_service = _NotisFalso_()
    gestor.process_service = None
    gestor.status_label = _EtiquetaFalsa_()
    gestor.after = lambda ms, func=None, *a: None
    gestor._cancel_confirm = lambda: None
    gestor._inline_status = lambda *a: procs_vistos.append(a)
    gestor._require_double_tap = lambda token, button, aviso: True
    with _HilosSincronos():
        gestor.kill_pack("trabajo")
    assert not procs_vistos, (
        f"la guarda del Gestor corto con {procs_vistos!r}: el pack tiene "
        "categorias marcadas y la puerta comun las apagaria"
    )
    print("Pack con categorias supera las cuatro guardas OK (TASK-063).")


def test_acordeon_se_renderiza_en_pack_no_gaming_con_espejo_deshabilitado():
    """#3. El acordeon existe para cualquier pack, y el espejo no deja marcar dos.

    Por que discrimina: el control nacia DENTRO de `if pack.is_gaming:`, asi
    que en un pack normal no habia nada que renderizar. Y el conflicto (una misma
    categoria en las dos listas) se evita en la UI deseleccionando la gemela al
    marcar la otra.

    Es una comprobacion ESTATICA, y lo sigue siendo, pero la RAZON por la que se
    escribio era FALSA y se corrige aqui, porque es la que ha invitado OCHO
    rondas de reescritura. Decia: "el arnes no abre ventana, y una casilla de
    CustomTkinter sin `CTk`/`root` no se puede instanciar". No es cierto, y esta
    MEDIDO en el propio arnes: `test_headless_ui` levanta un `WOptimizerApp`
    real con `app.run()`, y `test_main_window_navigation_transitions` monta un
    `ctk.CTk()` real, lo retira con `withdraw()` y llega a un `PackManagerView`
    DE VERDAD por `win._show_packs()`. El efecto es alcanzable desde aqui, y el
    3-E (abajo, `test_todo_pack_ofrece_el_catalogo_completo_en_apagar_y_arrancar`)
    lo mide con la vista montada de verdad.

    Lo que se congela en ESTE test es otra cosa, y no es menos: la PROPIEDAD
    DEL CABLEADO. Que el espejo existe, y que ninguna pieza del acordeon cuelga
    de una condicion (A0, A1 y A2 mas abajo) es sobre el CODIGO; lo que el
    usuario ve lo mide el 3-E, sobre la vista real. El desacuerdo esta
    MEDIDO, pero el mutante que se citaba como prueba se MIDIO MAL y se corrige
    aqui, porque era FALSO y lo era por el texto del propio techo:
    `E_COSMETICA_IF` (`cb.grid(row=i // (2 if pack.is_gaming else 1), ...)`) NO
    lo mata el techo (f) de mas abajo, ni el 3-E. El techo (f) declara
    "un bucle ENCIMA de la construccion cuyo ITERABLE es una eleccion de
    `is_gaming`" y su propio `COSMETICA_IF` es
    `if (2 if pack.is_gaming else 1) == 2:`, que cambia la CANTIDAD de
    widgets; la forma escrita cambia el `row=` y no la cantidad, de modo que
    cae FUERA de (f) por su propia definicion. MEDIDO con la suite entera:
    124/124 en VERDE. Los dos tienen razon en dejarla pasar, porque con ella
    las 18 casillas se siguen viendo, una por fila, y rechazarla seria el
    falso positivo del otro lado. El comportamiento de los servicios lo miden
    los tests #1 a #18.

    REGLA ANTI-RODADURA, la que impide la ronda 9: una familia nueva solo puede
    anadirse a una capa si NINGUNA regla de la OTRA capa la mata ya, y el techo
    se re-reparte de modo que cada eje declarado diga que capa lo posee. Por eso
    A1, A2 y A3 estan CONGELADAS: no se anaden formas "por si acaso" y no se
    tocan para "reforzar" lo que el 3-E ya mide, que seria la forma mas
    burda de relajar. Los dos docstrings citan la misma regla por eso.
    """
    print("Testing acordeon en pack no gaming con espejo deshabilitado...")
    ruta = os.path.join("src", "woptimizer", "ui", "views", "pack_manager_view.py")
    with open(ruta, encoding="utf-8") as fh:
        arbol = ast.parse(fh.read())

    # === TASK-063 iteracion 4: DE LA FORMA DEL GATE A LA PROPIEDAD DEL CABLEADO ==
    #
    # Las iteraciones 2 y 3 de este test Yardaron la FORMA del gate. La 2 exigia
    # que la condicion FUERA exactamente `pack.is_gaming`; la 3 que la CONTIENIERA
    # (con `ast.walk`). Las dos leen el NOMBRE de la lectura, y un test que
    # reconoce N formas de gate es un test que la forma N+1 ciega: la 3 cayo con
    # un `and`, y la 4 con las seis siguientes de la tabla del mutation-auditor
    # (variable intermedia, alias de `pack`, `getattr`, predicado extraido a un
    # metodo, helper y guard clause). Medido: con cualquiera de las seis los 123
    # tests seguian en verde y el acordeon se escondia a algun pack que hoy lo ve.
    #
    # Ademas las dos eran DEMASIADO ESTRICTAS, que es la otra mitad del mismo
    # defecto: rechazaban codigo legitimo (una casilla propia del Gaming Mode
    # dentro del badge `PRESET`, y un texto de aviso que dice "arrancar"), y el
    # mensaje de fallo de la primera afirmaba algo que no habia pasado. Quien
    # quisiera meter una opcion de solo-Gaming se encontraba el test en contra y
    # sin forma de escribir la excepcion: la salida natural era relajar el
    # predicado, o sea reabrir el agujero. Un test que obliga a aflojar es un
    # test que garantiza que se afloje.
    #
    # Aqui ya no se pregunta "¿la condicion menciona `is_gaming`?". Se pregunta
    # por el ESPACIO NEGATIVO del invariante, que es una PROPIEDAD y no una lista
    # de formas:
    #
    #   A0  el ESPEJO existe. Sin el, A1 y A2 mirarian el vacio.
    #   A1  ninguna pieza del acordeon cuelga de una condicion: ni por la forma de
    #       la condicion (da igual cual sea) ni por el iterable del bucle que la
    #       hospeda (una lista filtrada tambien la esconde).
    #   A2  ninguna funcion que dibuje una pieza vuelve antes si se cumple algo
    #       que dependa de si el pack es el de Gaming. El guard clause es la
    #       forma de gate que NO es antecesor, y por eso se mide aparte; un
    #       `return` early por otra causa es legitimo y este test lo permite.
    #
    # Que una condicion "de gaming" siga existiendo alrededor del badge `PRESET`,
    # del boton de restaurar, del texto del Gaming Mode y de los dos ternarios
    # del borde es CORRECTO y este test lo permite: no se asserta nada de ellas.
    _CONDICIONALES = (ast.If, ast.IfExp, ast.While, ast.Try, ast.Match, ast.Assert)

    # Tabla de padres: lo que hace posible razonar sobre antecesentes sin
    # importar el modulo entero en memoria.
    _PADRES = {}
    for _nodo in ast.walk(arbol):
        for _hijo in ast.iter_child_nodes(_nodo):
            _PADRES[_hijo] = _nodo

    def _llamada(nodo):
        """Nombre de la llamada: `ctk.CTkCheckBox` -> `CTkCheckBox`."""
        f = nodo.func
        return f.attr if isinstance(f, ast.Attribute) else getattr(f, "id", "")

    # Que pieza ES el acordeon se decide por el CABLEADO, no por el nombre del
    # widget: la casilla de una categoria es la que lleva
    # `command=create_command(...)`, y el espejo es quien escribe en el pack
    # (`update_pack`) e impone el espejo apagar/arrancar. Una casilla propia del
    # Gaming Mode, o un texto de aviso, pueden seguir gateados por `is_gaming`
    # sin que este test los confunda con la rejilla de categorias -- que es
    # justo el falso positivo que se midio en la ronda 4.
    def _es_casilla_del_acordeon(nodo):
        """CTkCheckBox cuya opcion `command` invoca el ESPEJO."""
        if not isinstance(nodo, ast.Call) or _llamada(nodo) != "CTkCheckBox":
            return False
        return any(
            kw.arg == "command"
            and any(isinstance(s, ast.Call) and _llamada(s) == "create_command"
                    for s in ast.walk(kw.value))
            for kw in nodo.keywords
        )

    def _es_etiqueta_del_acordeon(nodo):
        """La etiqueta del boton que abre la seccion."""
        return isinstance(nodo, ast.Call) and _llamada(nodo) == "_texto_acordeon"

    ANCLAJES = []
    for _nodo in ast.walk(arbol):
        if isinstance(_nodo, ast.FunctionDef) and _nodo.name == "create_command":
            ANCLAJES.append((_nodo, "el espejo (def create_command)"))
        elif isinstance(_nodo, ast.Call) and _llamada(_nodo) == "create_command":
            ANCLAJES.append((_nodo, "el cableado de una casilla (create_command(...))"))
        elif _es_casilla_del_acordeon(_nodo):
            ANCLAJES.append((_nodo, "una casilla de categoria (CTkCheckBox)"))
        elif _es_etiqueta_del_acordeon(_nodo):
            ANCLAJES.append((_nodo, "la etiqueta del boton del acordeon"))

    # --- A0: sin el espejo y sin las casillas, A1 y A2 no mirarian nada ---------
    assert any("def create_command" in etiqueta for _, etiqueta in ANCLAJES), (
        "no aparece el ESPEJO (def create_command) en la vista: este test dejaria "
        "de mirar la seccion de categorias y un acordeon entero desaparecido "
        "pasaria por no mirarlo nada. Si el espejo cambio de nombre, esto NO se "
        "relaja: se actualiza el nombre aqui y se vuelve a comprobar el cableado"
    )
    assert any("casilla de categoria" in etiqueta for _, etiqueta in ANCLAJES), (
        "no aparece ninguna casilla de categoria (CTkCheckBox con "
        "command=create_command(...)): la rejilla ha desaparecido de la vista y "
        "este test no lo veria"
    )

    # --- A1: ninguna pieza del acordeon cuelga de una condicion ----------------
    # REGLA ANTI-RODADURA (docstring de este test): esta es la capa ESTATICA y
    # la otra es el 3-E. Una forma nueva solo entra aqui si el 3-E no la mata
    # ya, y al reves. A1/A2/A3 se CONGELAN por eso: no se ensanchan "por si
    # acaso" y no se tocan para "reforzar" lo que el efecto ya mide.
    # Da igual QUE condicion sea. Una variable intermedia, un alias, `getattr`,
    # un helper, un predicado con otro nombre, el identificador de otra cosa o
    # un `assert` siguen siendo una condicion por delante de la construccion, y
    # el resultado para el usuario es el mismo: un pack normal sin donde elegir
    # categorias, con un servicio que se las pregunta igual.
    for _nodo, _etiqueta in ANCLAJES:
        _condicion = None
        _padre = _PADRES.get(_nodo)
        while _padre is not None:
            if isinstance(_padre, _CONDICIONALES):
                _condicion = _padre
                break
            _padre = _PADRES.get(_padre)
        assert _condicion is None, (
            f"{_etiqueta} (L{_nodo.lineno}) cuelga de una condicion en "
            f"L{_condicion.lineno}: {ast.unparse(_condicion.test)[:90]!r}. El "
            "acordeon se dibuja en linea recta, para todos los packs: no importa "
            "que la condicion sea 'pack.is_gaming' a secas, con un 'and', con un "
            "'or', negada, leida de una variable intermedia, de un alias, con "
            "getattr, de un helper, o escrita con otro predicado"
        )

    # Y la lista que alimenta la rejilla no puede depender de `is_gaming`. Un gate
    # no tiene por que ser un `if` DELANTE: tambien puede ser la lista de
    # categorias ya filtrada, y entonces el acordeon se dibuja VACIO para un pack
    # normal con el test en verde. Aqui si se mira el NOMBRE de la lectura, y a
    # proposito: un `ordenar_categorias(cats) if cats else []` defensivo es
    # legitimo y no se parece en nada a un gate del Gaming Mode.
    def _lee_is_gaming(nodo):
        for s in ast.walk(nodo):
            if isinstance(s, ast.Attribute) and s.attr == "is_gaming":
                base = s.value
                if ((isinstance(base, ast.Name) and base.id == "pack")
                        or (isinstance(base, ast.Attribute) and base.attr == "pack")):
                    return True
        return False

    # TASK-063 ronda 5. Estas tres piezas mas `_depende_de_is_gaming` son lo que
    # hace TRANSITIVA la resolucion, y el motivo esta medido: la version
    # anterior resolvia UN salto (el iterable y el valor de la asignacion al
    # nombre que el bucle lee), y con un nombre mas entre medias la veia pasar.
    # Medido, con la forma que escribe un humano --`cats_visibles = all_cats if
    # pack.is_gaming else []`-- un pack normal se quedaba con 0 de 3 categorias y
    # los 123 tests seguian en verde: es el fallo de U1 en dos lineas.
    def _menciona_is_gaming(nodo):
        """CUALQUIER lectura de `.is_gaming`, sin mirar la base.

        Hace falta porque el gate puede dejar de nombrarse: si otra funcion
        escribe `self._flag = p.is_gaming` y esta vista decide con `if not
        self._flag`, la condicion ya no dice `is_gaming` pero SI depende de el.
        Apropiarse del valor se propaga solo con esto.
        """
        return any(isinstance(s, ast.Attribute) and s.attr == "is_gaming"
                   for s in ast.walk(nodo))

    def _lecturas(nodo):
        """Nombres y atributos que el nodo LEE; los que escribe no cuentan."""
        _r = set()
        for s in ast.walk(nodo):
            if isinstance(s, ast.Name) and isinstance(s.ctx, ast.Load):
                _r.add(s.id)
            elif isinstance(s, ast.Attribute) and isinstance(s.ctx, ast.Load):
                _r.add("." + s.attr)
        return _r

    def _destinos(escritura):
        """A que nombres escribe una sentencia de asignacion."""
        _cola = list(escritura.targets) if isinstance(
            escritura, ast.Assign) else [escritura.target]
        _r = set()
        while _cola:
            _t = _cola.pop()
            if isinstance(_t, ast.Name):
                _r.add(_t.id)
            elif isinstance(_t, ast.Attribute):
                _r.add("." + _t.attr)
            elif isinstance(_t, (ast.Tuple, ast.List)):
                _cola.extend(_t.elts)
        return _r

    # Que nombres dependen de `is_gaming` se decide a punto fijo y sobre TODO el
    # modulo, no en una pasada: el orden de las lineas da igual y asi un nombre
    # marcado en la linea 40 marca a los que lo usan en la 200. Cada vuelta
    # marca al menos un nombre o para, asi que el numero de escrituras acota
    # las vueltas y el bucle no puede colgarse.
    ESCRITURAS = [n for n in ast.walk(arbol)
                  if isinstance(n, (ast.Assign, ast.AugAssign, ast.AnnAssign))
                  and n.value is not None]
    TAINT = set()
    for _ in range(len(ESCRITURAS) + 1):
        _nuevas = set()
        for _e in ESCRITURAS:
            if not (_menciona_is_gaming(_e.value)
                    or (_lecturas(_e.value) & TAINT)):
                continue
            _nuevas |= {d for d in _destinos(_e) if d not in TAINT}
        if not _nuevas:
            break
        TAINT |= _nuevas

    def _depende_de_is_gaming(nodo):
        """El nodo es una funcion de si el pack es el de Gaming, directa o no."""
        return _menciona_is_gaming(nodo) or bool(_lecturas(nodo) & TAINT)

    def _escritura_gateada(escritura):
        """La escritura va dentro de un `if` que depende de `is_gaming`.

        Una escritura gateada no se ve leyendo su VALOR --`all_cats = set()`
        dentro de `if not pack.is_gaming:` no menciona nada-- pero el nombre que
        escribe si depende de la condicion, asi que la lista que lo hereda
        tambien.
        """
        _padre = _PADRES.get(escritura)
        while _padre is not None and not isinstance(
                _padre, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)
        ):
            _test = getattr(_padre, "test", None)
            if _test is not None and _depende_de_is_gaming(_test):
                return True
            _padre = _PADRES.get(_padre)
        return False

    def _ultima_asignacion(nombre, funcion, antes_de):
        """La ultima escritura a `nombre` dentro de `funcion` y antes de la linea."""
        _c = [a for a in ast.walk(funcion)
              if isinstance(a, ast.Assign) and a.lineno < antes_de
              and any(isinstance(t, ast.Name) and t.id == nombre for t in a.targets)]
        return max(_c, key=lambda a: a.lineno) if _c else None

    def _funcion_que_alimenta(bucle):
        _padre = _PADRES.get(bucle)
        while _padre is not None and not isinstance(
                _padre, (ast.FunctionDef, ast.AsyncFunctionDef)
        ):
            _padre = _PADRES.get(_padre)
        return _padre

    # Una COMPREHENSION tambien es un bucle, y esto no es inventar una regla:
    # sus generadores son nodos `ast.comprehension`, cada uno con su `iter` y sus
    # `ifs`, y `[c for c in cats if pack.is_gaming]` es EXACTAMENTE la lista
    # filtrada que A1b mide, escrita con otra sintaxis. Medido en la ronda 7 con
    # la forma `LC`: sin esto la casilla construida dentro de una comprehension
    # se perdia al buscar el `For` ancestro --una `ListComp` no es `ast.For`, ni
    # una funcion, asi que la busqueda subia hasta el `FunctionDef` y el
    # `continue` de la ronda 5 la descartaba SIN MIRARLA-- y el acordeon se
    # dibujaba vacio para un pack normal con los 123 en verde. No era que la
    # cadena resolviera mal: es que nunca se le preguntaba.
    _BUCLES = (ast.For, ast.ListComp, ast.SetComp, ast.DictComp,
               ast.GeneratorExp)
    _CUERPO = (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)
    _COMPRENSIONES = _BUCLES[1:]

    def _lo_que_alimenta(bucle):
        """Los valores que meten elementos en el bucle.

        En un `for` es su `iter`. En una comprehension son los `iter` de sus
        generadores Y sus `ifs`, porque `for c in cats if <gate>` es una lista
        filtrada: el filtro es una condicion mas, no una lectura menos.
        """
        if isinstance(bucle, _COMPRENSIONES):
            return ([g.iter for g in bucle.generators]
                    + [c for g in bucle.generators for c in g.ifs])
        return [bucle.iter]

    for _nodo, _etiqueta in ANCLAJES:
        if "casilla de categoria" not in _etiqueta:
            continue
        # Se resuelven TODOS los bucles que envuelven la casilla, del mas
        # interior al mas exterior, y no solo el primero. Medido en la ronda 7
        # con la forma `LC_ANIDADA` y en las DOS direcciones: resolver solo el
        # mas interior --la comprehension-- hacia que la casilla sobreviviera,
        # y esa misma forma la mataba el test de antes. Perder una muerte es
        # peor que declarar un limite, asi que se miran todos. Con la vista
        # real no cambia nada: sus casillas viven en dos `for` y no hay
        # comprehension en el camino, asi que la lista tiene un elemento.
        _bucles = []
        _padre = _PADRES.get(_nodo)
        while _padre is not None and not isinstance(_padre, _CUERPO):
            if isinstance(_padre, _BUCLES):
                _bucles.append(_padre)
            _padre = _PADRES.get(_padre)
        for _bucle in _bucles:
            _fuente = _funcion_que_alimenta(_bucle)
            if _fuente is None:
                continue
            # Se sigue la lista por los NOMBRES que usa, salto a salto y SIN
            # limite de saltos: una lista que alimenta el acordeon no puede
            # depender de `is_gaming` a traves de los saltos que haga falta.
            _culpable = None
            _vistos = set()
            _pendientes = _lo_que_alimenta(_bucle)
            while _pendientes and _culpable is None:
                _valor = _pendientes.pop()
                if id(_valor) in _vistos:
                    continue
                _vistos.add(id(_valor))
                if _depende_de_is_gaming(_valor):
                    _culpable = _valor
                    break
                for _s in _lecturas(_valor):
                    # Se mira CADA escritura del nombre, no solo la ultima: la
                    # que gana puede ser la inocua y dejar la gateada una linea
                    # antes.
                    _escrituras = [a for a in ast.walk(_fuente)
                                   if isinstance(a, ast.Assign)
                                   and a.lineno < _bucle.lineno
                                   and any(isinstance(t, ast.Name) and t.id == _s
                                           for t in a.targets)]
                    for _escritura in _escrituras:
                        if _escritura_gateada(_escritura):
                            _culpable = _escritura
                            break
                    if _culpable is not None:
                        break
                    _ganadora = _ultima_asignacion(_s, _fuente, _bucle.lineno)
                    if _ganadora is not None:
                        _pendientes.append(_ganadora.value)
            assert _culpable is None, (
                f"la casilla de L{_nodo.lineno} la dibuja el bucle de "
                f"L{_bucle.lineno}, pero la lista de categorias que lo alimenta "
                f"depende de `is_gaming`: L{_culpable.lineno}. Un gate no tiene "
                "por que ser un `if` delante: puede ser la lista filtrada --en la "
                "asignacion o en cualquier salto de la cadena--, o una escritura "
                "que va dentro de un `if` que depende de `is_gaming`, y entonces "
                "el acordeon se dibuja vacio para un pack normal con este test en "
                "verde. El bucle puede ser un `for` o una comprehension, que "
                "tambien es un bucle: `[c for c in cats if pack.is_gaming]` "
                "filtra igual que un `for` con la lista ya filtrada"
            )
    # --- A2: la funcion que dibuja una pieza no vuelve antes si decide por el pack
    # `if not pack.is_gaming: return` al principio de un metodo propio es la
    # forma de gate que NO es antecesor de la construccion, asi que A1 no la ve,
    # y por eso se mide aparte. Lo que se mira es la CONDICION, no que haya un
    # `if`: un guard por otra causa es legitimo y esta version lo permite --
    # `if not pack: return` (guard defensivo), `if not sorted_cats: return` (no
    # pintar una rejilla vacia) y `if categorias: return`, que es el patron que
    # esta misma clase ya usa mas abajo. Medido en la ronda 5: la version
    # anterior rechazaba los tres y su mensaje de fallo decia estar midiendo una
    # sola condicion, que no era cierto.
    #
    # Y la condicion se mira por su LECTURA DIRECTA, no por el valor del que
    # viene. Medido en la ronda 6, no supuesto: propagar el taint hasta aqui
    # rechazaba `if not card.winfo_exists(): return`, que es un guard de Tk
    # legitimo, porque `card` nace de `border_width=2 if pack.is_gaming else 1`
    # y por tanto su VALOR depende de `is_gaming`. El nombre de la condicion
    # (`card`) no dice nada de Gaming, asi que ese codigo tiene que pasar: la
    # propagacion por valor sirve para la LISTA, que es lo que A1b sigue, y
    # aplicarla aqui se comeria un widget entero sin motivo.
    def _funcion_que_lo_dibuja(nodo):
        _padre = _PADRES.get(nodo)
        while _padre is not None and not isinstance(
                _padre, (ast.FunctionDef, ast.AsyncFunctionDef)
        ):
            _padre = _PADRES.get(_padre)
        return _padre

    def _cuerpo_propio(funcion, nodo):
        """`nodo` es de `funcion` y no de una funcion anidada dentro de ella."""
        _padre = _PADRES.get(nodo)
        while _padre is not None:
            if _padre is funcion:
                return True
            if isinstance(_padre, (ast.FunctionDef, ast.AsyncFunctionDef,
                                   ast.Lambda, ast.ClassDef)):
                return False
            _padre = _PADRES.get(_padre)
        return False

    FUNCIONES = []
    for _nodo, _etiqueta in ANCLAJES:
        _funcion = _funcion_que_lo_dibuja(_nodo)
        if _funcion is not None and not any(_funcion is f for f in FUNCIONES):
            FUNCIONES.append(_funcion)

    for _funcion in FUNCIONES:
        for _ret in ast.walk(_funcion):
            if not isinstance(_ret, ast.Return) or not _cuerpo_propio(_funcion, _ret):
                continue
            _condicion = None
            _padre = _PADRES.get(_ret)
            while _padre is not None and _padre is not _funcion:
                if isinstance(_padre, _CONDICIONALES):
                    _condicion = _padre
                    break
                _padre = _PADRES.get(_padre)
            _test = getattr(_condicion, "test", None)
            assert _test is None or not _menciona_is_gaming(_test), (
                f"{_funcion.name} (L{_funcion.lineno}) dibuja una pieza del acordeon "
                f"y ademas vuelve en L{_ret.lineno} si se cumple "
                f"{ast.unparse(_test)[:90]!r}, que depende de si el pack es el de "
                "Gaming: el guard clause 'if not pack.is_gaming: return' es la "
                "forma de gate que NO es antecesor de la construccion, y por eso se "
                "mide aparte. Un 'return' early por otra causa es legitimo y este "
                "test lo permite; lo unico vetado es el que decide por el pack de "
                "Gaming. El resultado para el usuario es el mismo: sin donde "
                "elegir categorias"
            )

    # --- A3: ninguna sentencia ANTERIOR puede impedir la construccion ---------
    # Un `assert` NO puede ser el antecesor de la construccion --una sentencia no
    # contiene a otra--, asi que el que se pone delante de la seccion es un
    # HERMANO, y la cadena de padres que mira A1 lo salta entera. MEDIDO en la
    # ronda 8 (`ASSERT_GATE`) y reproducido en la 9: con `ast.Assert` dentro de
    # `_CONDICIONALES` y nada mas, el mutante seguia VERDE, tambien con el
    # `assert` dentro del bucle de las casillas, porque la cadena real de la
    # casilla (`Call <- Assign <- For <- _render_pack_card`) no contiene ni un
    # `Assert` -- cero, medido con `ast`. Meter el nodo en la tupla no era el
    # arreglo, era una entrada que no puede funcionar; se queda porque un
    # `assert` que CONSTRUYA si es antecesor, y esa forma A1 la ve con el.
    #
    # La PROPIEDAD que faltaba es otra, y no es una forma mas: ninguna sentencia
    # ejecutada ANTES de la construccion puede impedir que se llegue a ella. La
    # que lo hacen son las que TRANSFIEREN el control, y de ellas solo interesan
    # las que dependen de si el pack es el de Gaming. Un `if` anterior no estorba
    # (se ejecuta antes y no impide nada), uno que construya lo mide A1 y uno que
    # devuelva, A2. Una llamada que reviente no se ve, y eso lo dice el fallo.
    _TRANSFIEREN = (ast.Assert, ast.Raise, ast.Return, ast.Continue, ast.Break)

    def _impide_llegar(nodo):
        """La sentencia previa que TRANSFIERE el control y depende del pack."""
        _n = nodo
        while True:
            _p = _PADRES.get(_n)
            if _p is None or isinstance(_p, ast.Module):
                return None
            _cuerpo = getattr(_p, "body", None)
            if isinstance(_cuerpo, list):
                for _s in _cuerpo:
                    if _s is _n:
                        break
                    if isinstance(_s, _TRANSFIEREN) and _depende_de_is_gaming(_s):
                        return _s
            if isinstance(_p, _CUERPO):
                return None
            _n = _p

    for _nodo, _etiqueta in ANCLAJES:
        _impide = _impide_llegar(_nodo)
        assert _impide is None, (
            f"{_etiqueta} (L{_nodo.lineno}) no llega a construirse: la sentencia "
            f"de L{_impide.lineno} ({ast.unparse(_impide)[:70]!r}) ABORTA si se "
            "cumple algo que depende de si el pack es el de Gaming, y va POR "
            "DELANTE de la construccion como hermana, no como antecesor, que es "
            "lo que A1 no mira. La forma medida es `assert pack.is_gaming` "
            "delante de la seccion: el pack normal se queda sin donde elegir "
            "categorias, y con `python -O` no se dibuja en silencio"
        )

    # Lo que este test NO cubre, dicho para que la proxima ronda lo mida en vez
    # de suponerlo. Las seis se MIDIERON vivas (rondas 5, 6 y 8) y ninguna se
    # corrige aqui: cazarlas seria inventarse una regla mas que un dia
    # rechazaria codigo legitimo, que es la trampa que este test lleva ocho
    # rondas evitando. La (f) es el PRECIO del arreglo de la ronda 7 y tambien
    # esta medida, no supuesta.
    #   (a) un gate en el LUGAR DE LA LLAMADA --`if pack.is_gaming:
    #       self._render_pack_card(pack)`-- no se ve, porque `refresh_packs` YA
    #       condiciona de legitimo ("el Gaming primero", "el resto, sin repetir el
    #       Gaming") y ninguna regla de este test puede distinguir una de la otra
    #       sin ser otra vez un test de forma. Lo mismo con la seccion extraida a
    #       un `def` anidado cuya llamada se gatea: desaparece el acordeon, no la
    #       tarjeta.
    #       Y la EXTRACCION no tiene que ser un `def`. MEDIDO en la ronda 8 con
    #       las TRES formas de esta misma decision, las tres con el gate en la
    #       llamada o en el iterable: `def _caja(cat)` + `list(map(_caja, cats
    #       if pack.is_gaming else []))`, la MISMA cosa con un `lambda` en vez de
    #       un `def`, y `(lambda c: CTkCheckBox(...))(c)` DENTRO de la
    #       comprehension cuyo iterable si esta gateado. Las tres dejan el pack
    #       normal con 3 de las 6 casillas y las tres salen PERMITIDAS. El
    #       motivo es UNO y no es la palabra `def`: una casilla construida dentro
    #       de un `Lambda` no la ve NINGUNA de las dos reglas, porque el
    #       `Lambda` es un CUERPO para A1b --la busqueda de bucles ancestros se
    #       para ahi y con ella se pierde la comprehension que la alimenta-- y
    #       porque el gate de A1 no le es ANTECESOR: esta en el argumento de
    #       `map()` o en el `iter` de la comprehension, que son subarboles
    #       HERMANOS de la casilla, no antecesores. Asi que el invariante que
    #       queda declarado es "ninguna pieza del acordeon se construye dentro de
    #       un `Lambda`", y el caso que de verdad faltaba en el texto era el
    #       TERCERO: sin `def`, sin extraccion y con la comprehension GATEADA,
    #       que es justo el bucle que el arreglo de la ronda 7 dice medir. Las
    #       dos primeras ya caian aqui por el MOTIVO --la llamada se gatea, la
    #       seccion desaparece-- y no por la palabra, asi que el texto nombra el
    #       caso y no ensancha la lista de palabras: `MAP_LAMBDA_2`, que mete el
    #       `if` en el cuerpo del `lambda` de fuera, sigue MUERIENDO en A1.
    #   (b) gatear la llamada a `.pack()`/`.grid()` que hace VISIBLE la rejilla, o
    #       el `.pack_forget()` del boton que la abre, dejando las casillas
    #       construidas: el cableado y A1 siguen viendo la construccion entera.
    #   (c) un `.destroy()` POSTERIOR sobre la casilla ya construida: A1 vigila la
    #       construccion, y esa ya esta hecha. Nada mira lo que pasa despues.
    #   (d) una lista filtrada que llega de OTRA funcion por una llamada --`cats =
    #       self._categorias_visibles(pack)`--: la cadena sigue las ASIGNACIONES
    #       del fichero que dibuja, no lo que devuelve una llamada. El GATE si se
    #       propaga entre funciones, por `_depende_de_is_gaming` y por
    #       `_escritura_gateada`; el VALOR que devuelve una llamada, no.
    #   (e) un guard clause cuya condicion depende de `is_gaming` SOLO a traves de
    #       una LECTURA INDIRECTA, con TRES exponentes, los tres MEDIDOS vivos: un
    #       atributo que pone otra funcion (`self._flag = p.is_gaming`, LIMITE_E),
    #       un ALIAS LOCAL (`_g = pack.is_gaming`, ALIAS_GUARD) y un PREDICADO EN
    #       UN METODO (`self._es_gaming(pack)`, GUARD_METODO). Los tres caen por el
    #       motivo del eje, no por la palabra: A2 mira la LECTURA DIRECTA de la
    #       condicion, no el valor. Decision MEDIDA: al propagarlo caian los tres,
    #       pero con el caia tambien `if not card.winfo_exists(): return`, guard
    #       de Tk legitimo (`card` nace de `border_width=2 if pack.is_gaming else
    #       1`). Si el valor acaba alimentando la LISTA, A1b lo ve: es el M3B.
    #   (f) MEDIDO en la ronda 7 y Remedido en la 8, y es el precio de contar
    #       las comprehensions como bucles: un bucle ENCIMA de la construccion
    #       cuyo iterable es una eleccion de `is_gaming` se rechaza. El motivo
    #       NO es cosmetico --la ronda 7 lo decia y era FALSO, y por eso se
    #       corrige--: con el `for` --`for _n in range(2 if pack.is_gaming else
    #       1):` envolviendo la fila-- el pack de Gaming construye NUEVE
    #       casillas y la fila sale DUPLICADA, y con el `if` --`if (2 if
    #       pack.is_gaming else 1) == 2:`-- el pack NORMAL se queda con TRES de
    #       las seis, o sea pierde entera la tanda de arrancar. Medido con el
    #       ejecutor de casillas CONSTRUIDAS, no contando `ast`: repo 6/6,
    #       `COSMETICA_FOR` 9/6, `COSMETICA_IF` 6/3. Las dos cambian lo que el
    #       usuario ve y no hay version legitima de un bucle cuya cantidad de
    #       widgets la decide el pack, asi que las dos tienen que morir. La del
    #       `if` ya la rechazaba A1 antes de este cambio: no es una regla nueva
    #       sino la MISMA invariante escrita con la sintaxis del bucle, "ninguna
    #       pieza del acordeon cuelga de algo que dependa de si el pack es el de
    #       Gaming". Se eligio porque la alternativa medida era peor: resolver
    #       solo el bucle mas interior dejaba viva la forma `LC_ANIDADA` (la
    #       casilla en una comprehension limpia dentro de un `for` gateado), que
    #       el test de `5f96671` mataba. Perder una muerte es peor que declarar
    #       un limite.
    #       Y el limite es estrecho DE VERDAD, no por cortesia: lo que el pack
    #       no puede decidir es la CANTIDAD de casillas, y en eso esta todo. Si
    #       puede decidir cuantos BUCLES la envuelven --`FP_DOS_TANDAS`, dos
    #       `for` anidados con el de fuera sobre la constante `(False, True)`--
    #       o en que columna se coloca cada una --`FP_COLUMNAS`, `column=i % (2
    #       if pack.is_gaming else 1)` DENTRO de `.grid()`-- el codigo es
    #       legitimo y pasa: las dos sondas se MIDIERON PERMITIDAS en la ronda 8.
    # Ninguno de los seis envuelve la construccion construyendola: (a), (b) y
    # (c) la dejan hecha y la ocultan, (d) y (e) ni la tocan, y (f) la envuelve
    # en un bucle que SI la construye, pero con la CANTIDAD de casillas --la
    # lista o el numero de vueltas-- decidida por el pack: 9/6 con el `for` y
    # 6/3 con el `if`, medido con el ejecutor, no supuesto.
    # De las trece formas que midio el mutation-auditor, las DOCE que envuelven
    # la construccion las mata A1 o A2 (once A1 y una A2); la treceava --el
    # guard clause con el guard de TASK-062 sin desatar-- murio de otro test y
    # por otro motivo: lo que detecto fue "la seccion se movio de metodo", no
    # que el acordeon estuviera gateado. Y ninguna de las trece es un death de
    # la tabla de 11.2, que tiene DOCE filas de gate mas dos sondas legitimas.

    with io.open(ruta, encoding="utf-8") as fh:
        cod = _codigo_ejecutable(fh.read())
    assert "categorias_disponibles" in cod, (
        "el catalogo tiene que salir del servicio: leer process_db o repetir los "
        "ocho nombres a mano son las dos formas que este cambio elimina"
    )
    assert "process_db" not in cod, "la vista no puede leer la DB de procesos"
    assert cod.count("pack.start_categories") >= 2, (
        "la columna de arrancar tiene que existir y leer su propia lista"
    )
    assert cod.count("pack.target_categories") >= 2, (
        "la columna de apagar tiene que seguir leyendo su lista"
    )
    assert "v_arrancar.set(0)" in cod and "v_apagar.set(0)" in cod, (
        "el conflicto debe evitarse en la UI deseleccionando la gemela al marcar "
        "la otra; si no, el usuario puede construir la misma categoria en las dos"
    )
    print("Acordeon en pack no gaming con espejo OK (TASK-063).")


def test_start_categories_arranca_y_cuenta_honestamente():
    """#4. `start_categories` arranca lo resoluble, y lo no resoluble va a `failed`.

    Por que discrimina: el campo no existia y las dos puertas de arranque solo
    leian `apps`. Ademas el techo es real (la DB guarda categoria, prioridad y
    descripcion, y NINGUNA ruta), asi que hay nombres que no resuelven: esos van
    a `failed` y NUNCA a `started`. Con un `started` inflado, la UI pinta en
    verde un "0 apps iniciadas" que no ocurrio.
    """
    print("Testing start_categories arranca y cuenta honestamente...")
    import tempfile as _tf
    with _tf.TemporaryDirectory() as tmp:
        ruta_ok = os.path.join(tmp, "woptimizer_t063_ok.exe")
        _exe_de_prueba(ruta_ok)
        svc = _ServicioDeArranque(tmp)
        # El catalogo se sobreescribe para que apunte al ejecutable que existe.
        svc._patrones_de_categoria = lambda cat: (
            ["woptimizer_t063_ok.exe", "woptimizer_t063_inexistente.exe"]
            if cat == _CAT_NAV else []
        )
        started, failed = svc.start_pack_categories([_CAT_NAV])
        assert started == 1, (
            f"solo el ejecutable que resuelve debe arrancar: started={started} "
            f"lanzados={svc.lanzados}"
        )
        assert failed == 1, (
            f"el nombre que no resuelve va a failed, NUNCA a started: failed={failed}"
        )
        assert svc.lanzados == [ruta_ok], (
            f"no debe lanzarse nada mas que lo resoluble: {svc.lanzados}"
        )
        # Una categoria con NINGUN ejecutable resoluble: 0 arrancados y >0 con
        # error. Es lo que evita el toast verde con 0 apps iniciadas.
        started2, failed2 = svc.start_pack_categories([_CAT_LANZ])
        assert started2 == 0 and failed2 >= 1, (
            "una categoria sin ejecutable resoluble no es exito: "
            f"started={started2} failed={failed2}"
        )
        # TASK-068 T-2, FILA 3: EL CONTROL NEGATIVO. Una categoria CON ejecutable
        # resoluble tiene que seguir dando `failed == 0`. Sin esta fila, el
        # mutante "cuenta de mas" --poner el `failed += 1` en el `return` en vez
        # de en la rama-- hace que TODO falle y las filas 1 y 2 siguen verdes:
        # esta es la que distingue CONTAR LO OMITIDO de CONTAR TODO.
        svc._patrones_de_categoria = lambda cat: (
            ["woptimizer_t063_ok.exe"] if cat == _CAT_CHAT else []
        )
        started3, failed3 = svc.start_pack_categories([_CAT_CHAT])
        assert (started3, failed3) == (1, 0), (
            "una categoria que SI arranca tiene que devolver (1, 0): si devuelve un "
            f"fallo, el contador cuenta de mas y no solo lo omitido. "
            f"recibido ({started3}, {failed3})"
        )
    print("start_categories arranca y cuenta OK (TASK-063, TASK-068).")


def test_la_barrera_roja_sigue_dentro_de_la_puerta_comun():
    """#5 (🔴 EL LADRILLO DEL CICLO 14). La barrera roja esta DENTRO de `execute_pack`.

    Por que discrimina, y por que el snapshot lleva `svchost` REAL: si la
    barrera se quedase pegada a `execute_gaming_pack` y la puerta comun no la
    repitiese, TODOS los tests de gaming seguirian verdes --el Gaming entra por
    la puerta restringida, que conserva la barrera--. Y como
    `is_system_protected('svchost')` es `False`, el blindaje de NOMBRES no lo
    salva: la unica red que puede cazarlo es la categoria roja. Un nombre
    inventado no discriminaria nada, porque el filtro caeria por otra parte.

    MEDIDO y corregido el 2026-10-03 (iteracion 3, mutation-auditor): este
    docstring decia que con la barrera solo pegada a `execute_gaming_pack`
    "solo este caeria". ES FALSO, y el falso era el mutante S1Z1 de la ronda 1:
    dejo 120/120 en verde. La razon real es la que se dice mas abajo y en la fila
    109 de `testing-guide.md`: aqui el snapshot trae `svchost` con la categoria
    ROJA, de modo que la falta de G1 la tapa G5 sobre `p.category`. Lo que mata
    a S1Z1 es caer G1 **y** G5 a la vez, o el test 121, que pone el snapshot y
    la DB en desacuerdo. Si vuelve a decir "solo este", es que nadie ha leido
    esto.
    """
    print("Testing la barrera roja sigue dentro de la puerta comun...")
    from woptimizer.services.gaming_service import GamingService

    pack_s, tmp_path = _pack_service_temporal()
    try:
        spy = _ProcessServiceSpy()
        spy.snapshot = [
            ProcessInfo(name="svchost", full_name="svchost.exe", pid=3001,
                        category=_CAT_ROJO),
            ProcessInfo(name="onedrive", full_name="onedrive.exe", pid=3002,
                        category=_CAT_SYNC),
        ]
        gs = GamingService(spy, pack_s)
        pack = Pack(
            id="usuario", name="Pack de usuario", default_action="kill",
            apps=[], target_categories=[_CAT_ROJO, _CAT_SYNC],
        )
        # Precondicion: sin esto el test no distinguiria la barrera del blindaje.
        assert ProcessService.is_system_protected("svchost") is False, (
            "precondicion rota: si svchost estuviera en el blacklist de nombres, "
            "este test ya no mediria la barrera de categoria"
        )
        killed, failed, skipped, freed_mb = gs.execute_pack(pack)
        # OJO: `kill_processes` del doble devuelve SIEMPRE (2, 0, 0, 12.5), asi
        # que `killed` no dice nada sobre la lista. El discriminante esta en lo
        # CAPTURADO y en `skipped`, que si lo calcula la puerta: `skipped` sube
        # con los descartes del filtro, y por eso un `svchost` que se colase se
        # veria como `skipped == 0`.
        nombres = [p.full_name for p in spy.capturados]
        assert nombres == ["onedrive.exe"], (
            "solo onedrive debe llegar a kill_processes (categoria verde marcada): "
            f"llegaron {nombres}"
        )
        assert "svchost.exe" not in nombres, (
            "svchost con la categoria roja marcada llego a kill_processes: sin la "
            "barrera DENTRO de la puerta comun se matan todos los svchost.exe y "
            "Windows queda inservible"
        )
        assert skipped == 1, (
            f"svchost debe contar como protegido, no desaparecer: skipped={skipped} "
            f"(con 0, la barrera no lo esta descartando y se cuela por otra parte)"
        )
    finally:
        os.unlink(tmp_path)
    print("La barrera roja sigue dentro de la puerta comun OK (TASK-063).")


def test_categoria_roja_en_start_categories_no_arranca():
    """#6. Una categoria 🔴 marcada para ARRANCAR no arranca nada.

    Por que discrimina: `svchost.exe` esta en System32, que no es una raiz de
    arranque, asi que sin la barrera `_resolver_app` devolveria None y el test
    pasaria por el motivo equivocado. Por eso el ejecutable de prueba esta en un
    temporal VALIDO: si la barrera no existiera, arrancaria 1.
    """
    print("Testing categoria roja en start_categories no arranca...")
    import tempfile as _tf
    with _tf.TemporaryDirectory() as tmp:
        _exe_de_prueba(os.path.join(tmp, "svchost.exe"))
        svc = _ServicioDeArranque(tmp)
        svc._patrones_de_categoria = lambda cat: (
            ["svchost.exe"] if cat == _CAT_ROJO else []
        )
        started, failed = svc.start_pack_categories([_CAT_ROJO])
        assert started == 0, (
            "una categoria roja debe ser INERTE tambien al arrancar: "
            f"started={started} lanzados={svc.lanzados}"
        )
        # TASK-068 T-2, FILA 1: lo omitido CUENTA. Antes este test miraba solo
        # `started == 0`, y con esa asercion sola la rama de omision podia hacer
        # `continue` pelado sin que NADIE se enterara: la puerta devolvia (0, 0)
        # y el toast salia en VERDE con "0 apps iniciadas", que es un rechazo
        # anunciado como exito. Ampliar el test que ya existe y no crear otro al
        # lado es lo que deja las dos ramas con un solo guardian.
        assert failed >= 1, (
            "una categoria marcada y omitida tiene que CUENTAR como fallo: si no, "
            "la puerta devuelve (0, 0) y el usuario ve un exito verde donde no "
            f"arranco nada. started={started} failed={failed}"
        )
        assert svc.lanzados == [], (
            f"no debe salir nada por la puerta de arranque: {svc.lanzados}"
        )
        # Y lo MISMO en la otra rama de omision, la del conflicto con
        # `target_categories`: son dos `continue` y las dos tienen que contar, o
        # el fix se queda en la mitad y vuelve el mismo verde por el otro lado.
        started_c, failed_c = svc.start_pack_categories([_CAT_CHAT], [_CAT_CHAT])
        assert (started_c, failed_c) == (0, 1), (
            "el conflicto con la lista de apagado tambien es una omision y tambien "
            f"cuenta: se recibio ({started_c}, {failed_c}) y tiene que ser (0, 1)"
        )
    print("Categoria roja en start_categories no arranca OK (TASK-063, TASK-068).")


