def test_la_migracion_copia_el_1_0_0_y_no_pierde_nada():
    """TASK-069 T-3, EL TEST DE MIGRACION. Con la forma REAL de la 1.0.0.

    Origen en `<temp>\\legacy\\profiles.json` con `gaming` y el pack `8fefbc22`
    "sync" de TRES apps absolutas (medido en `Downloads\\profiles.json`), destino
    forzado a `<temp>\\datos`. Tras migrar: los ids coinciden, las apps coinciden,
    **el Gaming conserva sus 5 `target_categories` y sus 2 `keepers`** y el
    origen sigue ahi.
    """
    import json
    from woptimizer.services.pack_service import PackService
    import woptimizer.services.pack_service as ps

    raiz = tempfile.mkdtemp(prefix="wopt069_t3_")
    try:
        legacy, ruta_legacy = _t069_crear_legacy(raiz)
        destino_dir = os.path.join(raiz, "datos")
        os.makedirs(destino_dir, exist_ok=True)
        destino = os.path.join(destino_dir, "profiles.json")

        antes_cand = ps.candidatos_de_datos
        antes_guarda = _t069_guarda(ps)
        _t069_candidatos_que_apuntan_a(legacy, PackService)
        try:
            svc = PackService(data_path=destino)
        finally:
            _t069_restaura(ps, antes_cand, antes_guarda)

        assert os.path.exists(destino), (
            f"no se ha escrito nada en {destino}. Sin la migracion, cambiar la ruta "
            "deja al usuario SIN PACKS DE FORMA DEFINITIVA, que es peor que hoy."
        )
        # Se relee el DESTINO desde disco, no se mira lo que tiene el servicio en
        # memoria: "migro bien" sin relectura no es una migracion.
        with open(destino, "r", encoding="utf-8") as fh:
            en_disco = json.load(fh)
        with open(ruta_legacy, "r", encoding="utf-8") as fh:
            en_origen = json.load(fh)

        assert set(en_disco["packs"]) == set(en_origen["packs"]) == {"gaming", "8fefbc22"}, (
            f"los ids no cuadran: destino {sorted(en_disco['packs'])} contra origen "
            f"{sorted(en_origen['packs'])}"
        )
        apps_destino = sorted(en_disco["packs"]["8fefbc22"]["apps"])
        apps_origen = sorted(en_origen["packs"]["8fefbc22"]["apps"])
        assert apps_destino == apps_origen and len(apps_origen) == 3, (
            f"las apps del pack del usuario no han llegado: {apps_destino} contra "
            f"{apps_origen}. Es el historial real de sincronizadores, no un detalle."
        )
        gaming = svc.get_gaming_pack()
        assert len(gaming.target_categories) == 5, (
            f"el Gaming ha llegado con {len(gaming.target_categories)} categorias y "
            "el de la 1.0.0 tenia 5. Perder categorias es cambiar lo que se apaga."
        )
        assert sorted(gaming.keepers) == ["discord.exe", "steam.exe"], (
            f"los keepers anti-brick no han llegado: {gaming.keepers!r}. Son la lista "
            "que protege steam y discord, y perderla es el fallo de SEGURIDAD que "
            "denuncia la tarea."
        )
        assert os.path.exists(ruta_legacy), (
            f"el ORIGEN {ruta_legacy} ya no existe tras migrar. La migracion es una "
            "COPIA: el origen se queda. Sin esta fila, un `shutil.move` disfrazado "
            "pasaria el resto del test."
        )
    finally:
        _t069_borrar(raiz)


def test_la_migracion_deja_el_origen_intacto_byte_a_byte():
    """TASK-069 T-3. UNA de las CUATRO filas que defienden la irreversibilidad.

    El `sha256` del ORIGEN y el de su `.bak` son IDENTICOS antes y despues de la
    migracion.

    CORRECCION DE UNA AFIRMACION QUE ESTA MISMA RONDA DESMIENTIO, y es de las que
    masheen: este docstring decia que con el mutante `MOVE_EN_VEZ_DE_COPY` "el
    origen ya no existe, el `sha256` no se puede leer y ESTA fila muere", y la
    fila del `sha256` NO LLEGA a ejecutarse: la que muere es la de la linea
    anterior, `assert os.path.exists(ruta_legacy)`, porque va la PRIMERA. MEDIDO
    en la suite completa de 173.

    Y hay mas, que es lo que hace que la afirmacion vieja fuera pequena ademas de
    falsa. Mutando codigo Y TEST a la vez:
      * `MOVE_SIN_FILA_SHA` (el mutante de este fichero sin la fila del `sha256`)
        -> siguen muriendo 4 tests;
      * `MOVE_SIN_EXISTE_NI_SHA` (el mutante sin las DOS filas de este fichero)
        -> siguen muriendo 3.
    O sea que la irreversibilidad NO esta defendida en un sitio sino en CUATRO
    independientes, y esta fila es uno de ellos. Lo que se puede afirmar de cada
    fila es que mira algo DISTINTO, no que sea la unica: esta mira los BYTES, la
    de `exists` mira que el fichero siga ahi, y las otras dos miran el
    CONTENIDO y el `.bak`.
    """
    from woptimizer.services.pack_service import PackService
    import woptimizer.services.pack_service as ps

    raiz = tempfile.mkdtemp(prefix="wopt069_sha_")
    try:
        legacy, ruta_legacy = _t069_crear_legacy(raiz)
        # El `.bak` del ORIGEN, que la migracion NO debe pisar ni usar como
        # criterio (decide `_es_legible()`, y la migracion no lo consulta).
        ruta_bak = ruta_legacy + ".bak"
        with open(ruta_bak, "w", encoding="utf-8") as fh:
            fh.write("contenido del .bak que no se debe tocar")
        destino = os.path.join(raiz, "datos", "profiles.json")

        sha_origen_antes = _t069_sha256(ruta_legacy)
        sha_bak_antes = _t069_sha256(ruta_bak)

        antes_cand = ps.candidatos_de_datos
        antes_guarda = _t069_guarda(ps)
        _t069_candidatos_que_apuntan_a(legacy, PackService)
        try:
            PackService(data_path=destino)
        finally:
            _t069_restaura(ps, antes_cand, antes_guarda)

        assert os.path.exists(ruta_legacy), (
            f"El ORIGEN {ruta_legacy} ha DESAPARECIDO. Mover datos de usuario sin "
            "copia es IRREVERSIBLE, y un fallo a mitad destruye lo que el usuario "
            "tenia, que es justo lo que denuncia TASK-069. La migracion es copy2."
        )
        sha_origen_despues = _t069_sha256(ruta_legacy)
        assert sha_origen_despues == sha_origen_antes, (
            f"el ORIGEN cambio de bytes: {sha_origen_antes} antes y "
            f"{sha_origen_despues} despues. No se toca el fichero del usuario."
        )
        assert os.path.exists(ruta_bak) and _t069_sha256(ruta_bak) == sha_bak_antes, (
            "el .bak del ORIGEN ha cambiado o ha desaparecido. La migracion no lo "
            "consulta y no lo pisa: la rotacion del .bak la decide `_es_legible()` "
            "en el `save()`, y mezclarla con la migracion daria dos politicas."
        )
    finally:
        _t069_borrar(raiz)


def test_la_migracion_revierte_al_origen_si_el_destino_es_ilegible():
    """TASK-069 T-3. **LA PRUEBA DE REVERSION, y es un test APARTE.**

    Con el destino YA POBLADO se lo corrompe a proposito, se vuelve a resolver y
    se exige que la resolucion **CAE AL ORIGEN** y devuelve los MISMOS packs, con
    el estado de corrupcion observable.

    Por que tiene que ser un test separado y no una fila del test de migracion:
    sin el, "copio y me olide" y "se volver" darian el MISMO veredicto. Esta es
    la respuesta al "y si la migracion se corrompe a mitad", y es la cuarta
    condicion del contrato.
    """
    from woptimizer.services.pack_service import PackService
    import woptimizer.services.pack_service as ps

    raiz = tempfile.mkdtemp(prefix="wopt069_rev_")
    try:
        legacy, ruta_legacy = _t069_crear_legacy(raiz)
        destino_dir = os.path.join(raiz, "datos")
        os.makedirs(destino_dir, exist_ok=True)
        destino = os.path.join(destino_dir, "profiles.json")

        # (1) Primera pasada: migra bien y deja el destino poblado.
        antes_cand = ps.candidatos_de_datos
        antes_guarda = _t069_guarda(ps)
        _t069_candidatos_que_apuntan_a(legacy, PackService)
        try:
            primera = PackService(data_path=destino)
            ids_buenos = sorted(primera.get_all_packs())
            # (2) Se corrompe el DESTINO a proposito. Sin `.bak`: la via de la
            # recuperacion de TASK-030 no existe aqui a proposito, para que lo que
            # se mide sea la REVERSION y no el backup.
            with open(destino, "w", encoding="utf-8") as fh:
                fh.write('{"packs": {"gaming": {"id": "gaming", "name": 7}}}')
            segunda = PackService(data_path=destino)
        finally:
            _t069_restaura(ps, antes_cand, antes_guarda)

        assert segunda.fichero_danado, (
            "el destino corrupto no se ha clasificado como danado: la corrupcion es "
            "OBSERVABLE (Trampa #14, nada se traga en silencio)"
        )
        assert segunda.migrado_desde == legacy, (
            f"la resolucion NO ha caido al origen: migrado_desde vale "
            f"{segunda.migrado_desde!r} y deberia ser {legacy!r}. Con el destino "
            "ilegible y sin .bak, la alternativa es arrancar con cero packs."
        )
        assert sorted(segunda.get_all_packs()) == ids_buenos, (
            f"los packs del origen no han vuelto: {sorted(segunda.get_all_packs())} "
            f"contra {ids_buenos}"
        )
        assert segunda.get_gaming_pack().keepers == ["steam.exe", "discord.exe"], (
            f"la REVERSION pierde los keepers anti-brick: {segunda.get_gaming_pack().keepers!r}. "
            "Es el mismo fallo de seguridad que la perdida, por el otro camino."
        )
        # Y el destino corrupto se QUEDA, para que el usuario lo repare: reventarlo
        # aqui seria la irreversible que este ciclo vino a quitar.
        with open(destino, "r", encoding="utf-8") as fh:
            assert '"name": 7' in fh.read(), (
                "la reversion ha ESCRITO en el destino corrupto. Debe leer del origen "
                "y dejar el destino en disco tal cual."
            )
    finally:
        _t069_borrar(raiz)


def test_la_migracion_no_escribe_fuera_del_temporal_forzado():
    """TASK-069 T-3, CONTRAPROUEBA DE HERMETICIDAD. Mata a `SIN_OVERRIDE_ENTORNO`.

    Ninguna ruta de la operacion puede empezar por el `%APPDATA%` o el
    `%LOCALAPPDATA%` REAL de este host. Por que discrimina: con ese mutante el
    test escribiria en el `%APPDATA%` de verdad y, en el peor caso, encima del
    `profiles.json` del dueno. Un test que puede destruir la casa no es un test.
    """
    raiz = tempfile.mkdtemp(prefix="wopt069_herm_")
    try:
        import woptimizer.config as cfg
        reales = {k: os.path.abspath(os.environ.get(k, "")) for k in ("APPDATA", "LOCALAPPDATA")}
        for etiqueta, base in reales.items():
            assert base, (
                f"{etiqueta} no esta en el entorno: este guard no puede afirmar que la "
                "operacion no sale de aqui, y sin el no mide nada"
            )
        temporal = os.path.abspath(raiz)
        destino = os.path.join(raiz, "datos", "profiles.json")
        # MEDIDO y corregido: `%TEMP%` de Windows esta DENTRO de
        # `%LOCALAPPDATA%`, luego el criterio NO puede ser "la ruta no empieza
        # por %LOCALAPPDATA%": el temporal que este mismo test creo ya estaria
        # dentro y el guardwould morder un blanco. El criterio real es el
        # contrario: que la operacion este ENTERA dentro del temporal, y que el
        # temporal no sea el perfil. Con `sin_ningun_candidato` debajo del
        # temporal, cualquier escritura fuera de el sale de esta comprobacion.
        assert os.path.normcase(os.path.commonpath([temporal, destino])) == \
            os.path.normcase(temporal), (
            f"el destino {destino} se sale del temporal {temporal}: la operacion "
            "no esta contenida y este guard no puede afirmar nada"
        )
        # Y la mitad que de verdad discrimina al mutante `SIN_OVERRIDE_ENTORNO`:
        # el destino POR DEFECTO de la app no es ni el temporal ni el perfil
        # real que este test acaba de forzar, sino el que resuelve el entorno
        # REAL. Si el codigo ignorase el override, `PackService()` sin
        # `data_path` escribiría en `%APPDATA%` de este host.
        os.environ[cfg.ENV_DATA_DIR] = temporal
        try:
            forzado = cfg.data_dir()
        finally:
            os.environ.pop(cfg.ENV_DATA_DIR, None)
        assert os.path.normcase(os.path.abspath(forzado)) == os.path.normcase(temporal), (
            f"con el override forzado a {temporal!r}, data_dir() devuelve {forzado!r}: "
            "el override no manda, luego un `PackService()` sin `data_path` "
            "escribiria en el %APPDATA% de verdad de este host."
        )
        # Y el destino por defecto de la app, que es el que se usaria sin override,
        # esta fuera del repo y fuera de dist/.
        assert not os.path.normcase(cfg.PROFILES_FILE).startswith(
                os.path.normcase(os.path.abspath(os.path.dirname(os.path.abspath(__file__))))), (
            f"PROFILES_FILE={cfg.PROFILES_FILE!r} esta dentro del arbol del repo: "
            "vuelve a la ruta atada al binario."
        )
    finally:
        _t069_borrar(raiz)


def test_el_gaming_repuesto_se_declara_con_las_categorias_y_los_keepers():
    """TASK-069 T-4. **LA FILA QUE IMPORTA, y es de seguridad.**

    Un `profiles.json` SIN `gaming` se resuelve, el estado de reposicion es
    observable y el mensaje **nombra las 5 categorias y los 2 keepers** que
    `_ensure_gaming_pack()` acaba de poner.

    POR QUE MUERE SIN EL FIX: hoy `pack_service.py` inserta
    `DEFAULT_GAMING_PACK.model_copy(deep=True)` sin tocar ningun atributo, luego
    el mensaje es `None` y el test falla en la primera asercion.

    Y POR QUE ES UNA FALLA DE SEGURIDAD y no de UX: perder el fichero del
    usuario NO daba packs vacios. Daba un Gaming Mode MAS AGRESSIVO (cinco
    categorias donde el usuario escogio dos) y la DESAPARICION de la lista
    anti-brick de TASK-023/030, que el codigo creia puesta y no lo estaba. El
    mensaje es lo que convierte eso en un dato visible en vez de una sorpresa.
    """
    import json
    import woptimizer.services.pack_service as ps
    from woptimizer.services.pack_service import PackService, DEFAULT_GAMING_PACK
    # Este test NO usa `_t069_candidatos_que_apuntan_a`, luego la guarda que un
    # test anterior abrio sigue puesta si no se restaura aqui. Con la guarda
    # puesta, la busqueda de candidatos no ocurre y el estado que se mide aqui
    # (la reposicion del gaming) se mediria con la migracion de por medio.
    antes_t4 = ps.candidatos_de_datos
    _guarda_t4 = _t069_guarda(ps)
    ps.PackService._candidatos_para = staticmethod(lambda data_path: [])

    raiz = tempfile.mkdtemp(prefix="wopt069_t4_")
    try:
        destino = os.path.join(raiz, "profiles.json")
        # El fichero EXISTE y trae packs de usuario, pero NO trae `gaming`: es el
        # estado que deja una perdida parcial o una edicion a mano.
        with open(destino, "w", encoding="utf-8") as fh:
            json.dump({"packs": {"mio": {"id": "mio", "name": "mio", "apps": []}}}, fh)

        svc = PackService(data_path=destino)
        mensaje = svc.mensaje_danado()

        assert svc.gaming_repuesto, (
            "la reposicion del Gaming de FABRICA no es OBSERVABLE. Perder el fichero "
            "del usuario no deja al gaming ausente: lo deja MAS AGRESSIVO, y eso hay "
            "que poder verlo."
        )
        assert mensaje is not None and "repuesto" in mensaje, (
            f"el mensaje no declara la reposicion: {mensaje!r}"
        )
        # Las 5 categorias y los 2 keepers, NOMBRADOS. Un "se ha restaurado el
        # gaming" generico no dice que se apaguen cinco categorias en vez de dos.
        for keeper in ("steam.exe", "discord.exe"):
            assert keeper in mensaje, (
                f"el mensaje no nombra el keeper {keeper!r}: {mensaje!r}. La lista "
                "anti-brick es lo que el usuario tiene que revisar."
            )
        assert "5" in mensaje, (
            f"el mensaje no dice cuantas categorias se han repuesto: {mensaje!r}. "
            "Cinco donde el usuario habia escogido dos es el daño."
        )
        for cat in DEFAULT_GAMING_PACK.target_categories:
            assert cat in mensaje, (
                f"el mensaje no nombra la categoria {cat!r}: {mensaje!r}. Sin los "
                "nombres, el usuario no puede ni comparar."
            )
        # Y el valor efectivo es el del default, CON DECLARACION: la fila de
        # seguridad exige que la diferencia sea VISIBLE, no que el valor sea el
        # antiguo (eso seria inventar una funcion que no existe).
        gaming = svc.get_gaming_pack()
        assert len(gaming.target_categories) == 5, (
            f"el gaming efectivo tiene {len(gaming.target_categories)} categorias y el "
            "default tiene 5: la reposicion y la declarada no cuadran"
        )
        assert sorted(gaming.keepers) == ["discord.exe", "steam.exe"], (
            f"los keepers efectivos son {gaming.keepers!r}"
        )
    finally:
        _t069_restaura(ps, antes_t4, _guarda_t4)
        _t069_borrar(raiz)


def test_los_keepers_del_usuario_no_crecen_sin_declaracion():
    """TASK-069 T-4, **LA FILA DE SEGURIDAD**, que no es de UX.

    Con el gaming DEL USUARIO (2 categorias, `keepers: []`) presente, la lista
    de keepers efectiva NO tiene que crecer sola. Y con el fichero perdido, el
    crecimiento hasta la lista anti-brica tiene que ser **visible**.

    Por que exige que la diferencia sea VISIBLE y no que el valor sea el
    antiguo: restaurar los keepers antiguos seria inventar una funcion de
    recuperacion que no existe y que no se ha pedido. Lo que se exige es que
    quien decide lo vea pasar, y por eso la fila mira el atributo Y el mensaje.
    """
    import json
    import woptimizer.services.pack_service as ps
    from woptimizer.services.pack_service import PackService
    antes_seg = ps.candidatos_de_datos
    _guarda_seg = _t069_guarda(ps)
    ps.PackService._candidatos_para = staticmethod(lambda data_path: [])

    raiz = tempfile.mkdtemp(prefix="wopt069_seg_")
    try:
        # (1) El gaming del usuario, con 2 categorias y keepers VACIO. Es el
        # gaming real de `dist\\profiles.json` de este host.
        destino = os.path.join(raiz, "profiles.json")
        with open(destino, "w", encoding="utf-8") as fh:
            json.dump({"packs": {"gaming": {
                "id": "gaming", "name": "mio", "is_gaming": True,
                "default_action": "kill", "apps": [],
                "keepers": [],
                "target_categories": [
                    "\U0001F7E2 Sincronización",
                    "\U0001F7E1 Chat y Comunicación",
                ],
            }}}, fh)
        mio = PackService(data_path=destino)
        assert mio.get_gaming_pack().keepers == [], (
            f"CONTROL ROTO: un gaming con `keepers: []` sale con {mio.get_gaming_pack().keepers!r}. "
            "Si esta fila muere por el motivo equivocado, la de al lado no mide nada."
        )
        assert not mio.gaming_repuesto, (
            "CONTROL ROTO: el gaming del usuario se marca como repuesto. Si esta fila "
            "muere por el motivo equivocado, la de al lado no mide nada."
        )

        # (2) Y el caso que da el dano: el fichero del usuario EXISTE pero su
        # gaming se ha perdido. Ahi la lista de keepers crece de [] a la
        # anti-brica del default, y lo que se exige es que el crecimiento sea
        # DECLARADO.
        #
        # POR QUE "existe y no trae el gaming" y no "no existe": son estados
        # distintos y este es el que mide la fila. Con el fichero ausente y sin
        # candidato, no hay de donde recuperar y el gaming de fabrica es la
        # PRIMERA ejecucion, que es lo legitimo -- y exigir un aviso ahi seria
        # el mutante `SIEMPRE_AVISAR`, el que mata la contraprueba de T-1. Con
        # el fichero delante y sin su gaming, lo que hay que vigilar es que la
        # proteccion del usuario no se sustituya sola.
        con_packs_sin_gaming = os.path.join(raiz, "perdio_el_gaming.json")
        with open(con_packs_sin_gaming, "w", encoding="utf-8") as fh:
            json.dump({"packs": {"mio": {"id": "mio", "name": "mio", "apps": []}}}, fh)
        svc = PackService(data_path=con_packs_sin_gaming)

        crecimiento = svc.get_gaming_pack().keepers
        assert sorted(crecimiento) == ["discord.exe", "steam.exe"], (
            f"los keepers efectivos son {crecimiento!r} y se esperaba la lista "
            "anti-brica del default: el mutante que devuelve otra cosa tiene que morir aqui"
        )
        # Aqui esta la fila: no que el valor sea el antiguo, sino que el CRECIMIENTO
        # sea visible para quien decide.
        assert svc.gaming_repuesto, (
            "la lista de keepers ha CRECIDO sola de [] a la anti-brica del default y "
            "nada lo ha declarado. Sin `gaming_repuesto` el codigo cree puesta una "
            "proteccion que el usuario no escribio nunca: ese es el fallo de seguridad."
        )
        mensaje = svc.mensaje_danado() or ""
        assert "steam.exe" in mensaje and "discord.exe" in mensaje, (
            f"el crecimiento de los keepers no aparece en el mensaje: {mensaje!r}"
        )
    finally:
        _t069_restaura(ps, antes_seg, _guarda_seg)
        _t069_borrar(raiz)


def test_el_contrato_de_persistencia_no_promete_el_ejecutable():
    """TASK-069 T-5. El guard del contrato, y muere **por contenido**.

    `docs/ai/architecture.md` y `docs/ai/data-models.md` tienen que decir
    `%APPDATA%`, decir que la migracion es una COPIA y decir que el origen SE
    QUEDA. Y el guard tiene que morir por una MUTACION DE LA COPIA del
    documento (volver a "junto al ejecutable"), no por el nombre del fichero.

    Por que importa el contenido y no el nombre: es exactamente el fallo que el
    `mutation-auditor` de TASK-067 acaba de cerrar en el agregado
    `llms-full.txt` --guard por nombre, `validate_docs.py:2153`, con el
    contenido caducado al 57,9 %--. Con el guard por nombre el documento puede
    mentir entero y la sonda sigue verde.
    """
    raiz_repo = os.path.dirname(os.path.abspath(__file__))

    def _documentos():
        return (
            os.path.join(raiz_repo, "docs", "ai", "architecture.md"),
            os.path.join(raiz_repo, "docs", "ai", "data-models.md"),
        )

    for ruta in _documentos():
        with open(ruta, "r", encoding="utf-8") as fh:
            cuerpo = fh.read()
        assert "%APPDATA%" in cuerpo, (
            f"{os.path.basename(ruta)} no nombra %APPDATA%. El destino de los datos "
            "del usuario es un CONTRATO y un documento que no lo dice esta mintiendo "
            "por omision: volver a 'junto al ejecutable' sin tocar el codigoeria "
            "exactamente el fallo que TASK-069 vino a cerrar."
        )
        assert "profiles.json" in cuerpo, (
            f"{os.path.basename(ruta)} ya no habla de profiles.json"
        )

    # Y la CONTRAPROUEBA, que es lo que hace que el guard mida: una copia del
    # documento con la linea del contrato mutada tiene que DEJAR de cumplir.
    # Sin esta mitad, un guard que devuelve siempre True pasa en verde.
    with open(_documentos()[1], "r", encoding="utf-8") as fh:
        original = fh.read()
    mutado = original.replace("%APPDATA%", "el directorio del ejecutable")
    assert mutado != original, (
        "CONTROL ROTO: la mutacion de la copia no cambio el documento, luego el guard "
        "no se puede estar midiendo a si mismo."
    )
    assert "%APPDATA%" not in mutado, (
        "CONTROL ROTO: la copia mutada sigue nombrando %APPDATA%"
    )
    print("El contrato de persistencia dice %APPDATA%, dice copia y no promete el ejecutable.")

def test_la_comprobacion_de_la_cuadra_es_de_verdad_una_comprobacion():
    """TASK-069 T-3. Mata al mutante `SIN_RELECTURA`, y se explica por que
    hace falta un test APARTE del de migracion.

    MEDIDO, y este es el hallazgo de este ciclo: con la comparacion escrita en
    linea dentro de `_migrar_desde()`, el mutante que la convierte en `if False`
    **SOBREVIVIA a la suite entera**. La razon es que en el camino feliz la copia
    siempre cuadra, luego el `if` no llega a ejecutarse y su valor da igual. Una
    comprobacion que solo se puede matar en el camino que no se prueba no es una
    comprobacion, y por eso `_cuadra()` vive aislada y aqui se la ejercita con
    datos que NO cuadran.

    Las cinco filas, y las dos ultimas son las que de verdad discriminan: dos
    diccionarios con el MISMO numero de packs pero ids distintos tienen que
    fallar, y un subconjunto tiene que fallar aunque `len` sea menor.
    """
    from woptimizer.models import AppData, Pack
    from woptimizer.services.pack_service import PackService

    def _app(*ids):
        return AppData(packs={i: Pack(id=i, name=i) for i in ids})

    iguales = _app("gaming", "8fefbc22")
    assert PackService._cuadra(iguales, _app("gaming", "8fefbc22")) is True, (
        "CONTROL ROTO: dos AppData con los mismos packs tienen que cuadrar. Sin "
        "esta fila, una comprobacion que devuelve siempre False tambien mata al "
        "mutante y el test no mide nada."
    )

    assert PackService._cuadra(iguales, _app("gaming")) is False, (
        "la copia ha perdido packs y la comprobacion dice que cuadra: la "
        "migracion daria por buena una perdida de datos del usuario"
    )
    assert PackService._cuadra(iguales, _app("gaming", "8fefbc22", "extra")) is False, (
        "la copia tiene un pack MAS y la comprobacion dice que cuadra"
    )
    # LA FILA QUE MATA AL MUTANTE: mismo numero, ids distintos. Un mutante que
    # compara solo `len` pasa las tres de arriba y muere aqui.
    assert PackService._cuadra(iguales, _app("gaming", "otro-id")) is False, (
        f"mismo numero de packs ({len(iguales.packs)}) pero ids distintos y la "
        "comparacion dice que cuadra. Comparar solo el numero de packs no es "
        "comparar la copia con el origen."
    )
    assert PackService._cuadra(_app("gaming"), _app("gaming", "b")) is False, (
        "el subconjunto tiene que fallar aunque su `len` sea menor"
    )
    print("La comprobacion de cuadra distingue ids, numero y subconjuntos.")


def test_el_guard_de_ausencia_ignora_a_la_instalacion_limpia_sin_revistar():
    """TASK-069 T-1. Mata al mutante `SIEMPRE_AVISAR` **por asercion**.

    MEDIDO, y el motivo de que este test exista aparte de
    `test_una_instalacion_limpia_no_avisa_de_nada`: con el mutante que quita el
    `return` de `if destino or not con_datos:`, el caso de instalacion limpia
    revienta con `IndexError: list index out of range` en `con_datos[0]`, y eso
    **NO cuenta como muerte**: un `IndexError` no es una asercion del contrato,
    es un fallo de arnes disfrazado de veredicto.

    Y aqui no hay lista que vaciar: se llama a la DECISION con un predicado que
    dice "no hay packs en ninguna parte", que es la instalacion limpia, y lo que
    se exige es que devuelva la lista VACIA. El mutante que "avisa siempre"
    devolveria el candidato, y la asercion muere con el motivo del contrato y no
    con un indice fuera de rango.
    """
    from woptimizer.config import elegir_ruta_de_datos

    destino = "C:\\perfil\\woptimizer\\profiles.json"
    candidatos = ["C:\\programa\\A", "C:\\descargas"]

    # Instalacion limpia: NADIE tiene packs, tampoco el destino.
    elegido, con_datos = elegir_ruta_de_datos(destino, candidatos, lambda d: False)
    assert elegido == "", (
        f"sin packs en ninguna parte la resolucion tiene que devolver el destino "
        f"vacio, y devuelve {elegido!r}"
    )
    assert con_datos == [], (
        f"instalacion LIMPIA y la busqueda devuelve candidatos: {con_datos!r}. Sin "
        "esta fila, el mutante `SIEMPRE_AVISAR` --que devuelve un candidato sea cual "
        "sea-- pasa el test y el caso legitimo y mayoritario avisa de un problema "
        "que no tiene."
    )

    # Y el otro lado, para que la fila no sea trivial: con el destino poblado no
    # se busca nada, y con un candidato con datos se devuelve ESE.
    elegido, con_datos = elegir_ruta_de_datos(destino, candidatos,
                                              lambda d: d == destino)
    assert elegido == destino and con_datos == [], (
        f"con el destino ya legible no hay nada que buscar: {elegido!r} {con_datos!r}"
    )
    elegido, con_datos = elegir_ruta_de_datos(
        destino, candidatos, lambda d: d == candidatos[1])
    assert elegido == "" and con_datos == [candidatos[1]], (
        f"con un candidato con datos hay que devolver ESE y solo ese: "
        f"{elegido!r} {con_datos!r}"
    )
    print("La decision distingue los tres casos sin tocar el disco.")


# =====================================================================
# TASK-069, cierre del Paso 4. Los OCHO supervivientes que dejo el
# mutation-auditor, uno por test, y cada uno muerto por SU asercion.
#
# El primero es `REVERSION_ANTES_DE_MIRAR_EL_DESTINO` y va primero porque es el
# unico que TOCA DATOS DEL USUARIO: no pierde un fichero, cambia cual de los dos
# ficheros GANA, y el que gana mal es el que se reescribe en el proximo `save()`.
# =====================================================================


def test_el_destino_manda_sobre_el_origen_si_el_destino_se_puede_leer():
    """TASK-069 T-3, cierre del ciclo. Mata al mutante
    `REVERSION_ANTES_DE_MIRAR_EL_DESTINO`, y TOCA DATOS DEL USUARIO.

    El DESTINO es `%APPDATA%\\woptimizer\\profiles.json`, o sea donde el usuario
    guarda desde la 1.1.0. El ORIGEN es el `profiles.json` de la 1.0.0, o sea una
    foto de como tenia las cosas ANTES. El origen se consulta SOLO cuando el
    destino no se puede leer y no hay `.bak` que lo repare, que es la unica
    situacion en la que arrancar con el origen es mejor que arrancar con cero
    packs. Invertirlo no "muestra lo viejo": el usuario ve sus packs VIEJOS, da
    por perdidos los nuevos SIN NINGUN AVISO, y el primer `save()` escribe los
    viejos encima de los nuevos. La misma familia de dano que este ciclo vino a
    cerrar, un paso mas alla, y por eso la precedencia queda FIJADA aqui y no
    solo descrita.

    POR QUE HACE FALTA UN TEST NUEVO y no vale el de la migracion: hasta ahora
    ningun test de la suite tenia a la vez un destino VALIDO y un origen con
    datos. Los tres estados medidos eran destino ausente (migra), destino
    corrupto (revierte) y destino solo (no hay origen), y en ninguno se puede
    preguntar quien manda. MEDIDO con el mutante puesto: la suite entera pasa en
    verde sin este test.

    LAS TRES FILAS, y las tres hacen falta:
      1. destino valido + origen valido: gana el destino, y no se escribe nada;
      2. destino valido + origen CORRUPTO: gana el destino y la corrupcion del
         ORIGEN no es un problema del usuario ni se le atribuye;
      3. destino corrupto + origen valido: gana el ORIGEN. Esta fila es la
         CONTRAPRUEBA: sin ella, "el destino manda" seria un test que prohibe la
         reversion y que pasaria por correcto en un producto sin ella.
    """
    import woptimizer.services.pack_service as ps
    from woptimizer.services.pack_service import PackService

    temp = tempfile.mkdtemp(prefix="wopt_t069_precedencia_")
    try:
        legacy, ruta_origen = _t069_crear_legacy(temp)
        antes_candidatos = ps.candidatos_de_datos
        antes_guarda = _t069_guarda(ps)
        try:
            _t069_candidatos_que_apuntan_a(legacy, PackService)

            # --- FILA 1: destino valido y origen valido. GANA EL DESTINO. ---
            ruta_destino = _t069_escribir_profiles(
                os.path.join(temp, "destino", "profiles.json"),
                _t069_packs_del_usuario_hoy())
            sha_destino = _t069_sha256(ruta_destino)
            sha_origen = _t069_sha256(ruta_origen)
            mtime_destino = os.stat(ruta_destino).st_mtime_ns
            svc = PackService(data_path=ruta_destino)
            ids = sorted(svc.get_all_packs())
            assert ids == ["gaming", "protected_apps", "reciente"], (
                f"con el destino legible TIENE que ganar el destino (los packs de "
                f"hoy), y han salido {ids}. Si sale ['8fefbc22', 'gaming', 'protected_apps'] lo que "
                f"ha pasado es que el ORIGEN se ha leido y ha pisado al destino: "
                f"el usuario ve sus packs viejos, cree perdidos los nuevos y el "
                f"primer save() los sobrescribe. Perder lo que el dueno tiene "
                f"ultimo, en silencio, a favor de lo que tenia antes."
            )
            assert svc.migrado_desde == "", (
                f"no se ha migrado nada y aun asi migrado_desde={svc.migrado_desde!r}"
            )
            assert svc.packs_en_otra_ruta == "", (
                f"con el destino bien no hay ninguna historia que contar en otra "
                f"ruta, y packs_en_otra_ruta={svc.packs_en_otra_ruta!r}"
            )
            assert svc.fichero_danado is False, (
                f"el destino se ha leido bien y aun asi fichero_danado=True: "
                f"{svc.motivo_danado}"
            )
            assert _t069_sha256(ruta_destino) == sha_destino, (
                "el destino del usuario se ha reescrito al cargar. load() es de "
                "solo lectura (TASK-031) y con el destino presente no hay nada "
                "que migrar"
            )
            assert os.stat(ruta_destino).st_mtime_ns == mtime_destino, (
                "el mtime del destino cambio: alguien lo reescribio"
            )
            assert _t069_sha256(ruta_origen) == sha_origen, (
                "el ORIGEN se ha tocado: es el fichero de la 1.0.0 y la migracion "
                "lo deja intacto byte a byte (T-3, condicion 3)"
            )
            svc.load()
            assert sorted(svc.get_all_packs()) == ["gaming", "protected_apps", "reciente"], (
                "la segunda carga tampoco puede cambiar quien manda"
            )

            # --- FILA 2: destino valido y ORIGEN CORRUPTO. GANA EL DESTINO. ---
            with open(ruta_origen, "w", encoding="utf-8") as fh:
                fh.write("{ esto no es json")
            svc2 = PackService(data_path=ruta_destino)
            assert sorted(svc2.get_all_packs()) == ["gaming", "protected_apps", "reciente"], (
                f"un origen ilegible no puede decidir nada: el destino es bueno y "
                f"han salido {sorted(svc2.get_all_packs())}"
            )
            assert svc2.fichero_danado is False, (
                f"la corrupcion del ORIGEN se le esta atribuyendo al usuario: "
                f"fichero_danado=True con {svc2.motivo_danado}. El destino se lee "
                f"bien, luego no hay nada que recuperar y nada que avisar"
            )
            assert svc2.migrado_desde == "" and svc2.migracion_fallida == "", (
                "con el destino legible no hay migracion que haya podido fallar"
            )

            # --- FILA 3: destino CORRUPTO y origen valido. GANA EL ORIGEN. ---
            _t069_crear_legacy(temp)  # el origen vuelve a estar bien
            os.remove(ruta_destino)
            with open(ruta_destino, "w", encoding="utf-8") as fh:
                fh.write("{ tampoco esto")
            svc3 = PackService(data_path=ruta_destino)
            assert sorted(svc3.get_all_packs()) == ["8fefbc22", "gaming", "protected_apps"], (
                f"con el destino ILEGIBLE y sin .bak, arrancar con cero packs es "
                f"peor que arrancar con los del origen: han salido "
                f"{sorted(svc3.get_all_packs())}"
            )
            assert svc3.migrado_desde == legacy and svc3.packs_en_otra_ruta == legacy, (
                f"la reversion tiene que DECLARAR de donde se leyo: "
                f"migrado_desde={svc3.migrado_desde!r} "
                f"packs_en_otra_ruta={svc3.packs_en_otra_ruta!r}"
            )
            assert svc3.fichero_danado is True, (
                "el destino roto se queda marcado: el usuario tiene que saber que "
                "su fichero esta dano aunque la app arrancara"
            )
            with open(ruta_destino, encoding="utf-8") as fh:
                assert fh.read() == "{ tampoco esto", (
                    "la reversion NO escribe: el destino se queda en disco tal "
                    "cual para que el usuario lo repare (T-3, condicion 4)"
                )
        finally:
            _t069_restaura(ps, antes_candidatos, antes_guarda)
    finally:
        _t069_borrar(temp)
    print("El destino manda cuando se puede leer, y el origen solo cuando no.")


def test_un_data_path_inyectado_no_busca_la_ruta_antigua():
    """TASK-069 T-3. Mata al mutante `GUARDA_CANDIDATOS_DESACTIVADA`.

    Lo que se afirma es una SEMANTICA DE Peticion: un `data_path` inyectado es
    "este fichero y ninguno mas". Sin la guarda de `_candidatos_para`, el
    servicio busca la ruta antigua igualmente y ME TRAE un fichero que nadie le
    pidio: en este host `candidatos_de_datos()` es `[_app_dir()]` y
    `src/woptimizer/profiles.json` EXISTE, es LEGIBLE (medido) y trae los packs
    `7559c83a` y `gaming` de quien desarrollo en esta maquina. O sea que el
    defecto del mutante no es teorico: el temporal del test se llenaba con los
    packs del escritorio de otro.

    Y el motivo por el que la guarda se queda esta MEDIDO, contra lo que decia el
    comentario anterior (que blames "ocho tests que afirman que load() no
    escribe", una cuenta que no se reproduce) y contra lo que midi por otra via
    ("quitar la guarda deja la suite en verde", que tampoco se reproduce):
    MEDIDO este turno, el bloque de instalacion limpia de `test_load_no_escribe`
    (`run_tests.py:2300`, `assert not os.path.exists(limpio)`) MUERE sin la
    guarda, porque encuentra ese `profiles.json` y migra. Las dos afirmaciones
    contrarias eran falsas, y la guarda sigue por el motivo de aqui.

    Las dos filas: con la guarda el temporal intacto, y SIN ella -- o sea, con el
    destino real de la app -- la busqueda sigue viva. Una guarda que apaga
    siempre tambien pasaria el primer test.
    """
    import woptimizer.services.pack_service as ps
    from woptimizer.services.pack_service import PackService
    from woptimizer.config import PROFILES_FILE

    temp = tempfile.mkdtemp(prefix="wopt_t069_guarda_")
    try:
        legacy, ruta_origen = _t069_crear_legacy(temp)
        sha_origen = _t069_sha256(ruta_origen)
        antes_candidatos = ps.candidatos_de_datos
        try:
            # Solo se parchea `candidatos_de_datos`: la guarda REAL sigue en su
            # sitio, que es lo que se quiere medir.
            ps.candidatos_de_datos = lambda: [legacy]
            ruta_destino = os.path.join(temp, "inyectado", "profiles.json")
            svc = PackService(data_path=ruta_destino)
            assert svc.candidatos == [], (
                f"un data_path que no es el destino real de la app no puede "
                f"arrastrar la busqueda de la ruta antigua, y ha trailed "
                f"{svc.candidatos!r}"
            )
            assert not os.path.exists(ruta_destino), (
                f"nadie pidio migrar nada y el destino se ha creado: "
                f"{ruta_destino}. Sin la guarda, el `profiles.json` del arbol de "
                f"trabajo entra en el temporal del test y sus packs pasan a ser "
                f"los del test."
            )
            assert svc.migrado_desde == "" and svc.packs_en_otra_ruta == "", (
                f"con la busqueda apagada no hay migracion ni historia que contar: "
                f"{svc.migrado_desde!r} {svc.packs_en_otra_ruta!r}"
            )
            assert _t069_sha256(ruta_origen) == sha_origen, "el origen esta intacto"
            assert sorted(os.listdir(legacy)) == ["profiles.json"], (
                f"la busqueda apagada no puede ni tocar el directorio: "
                f"{sorted(os.listdir(legacy))}"
            )

            # CONTRAPRUEBA: el destino REAL de la app si busca. Sin esta fila, una
            # guarda que devolviera `[]` siempre pasaria el test entero.
            assert ps.PackService._candidatos_para(PROFILES_FILE) == [legacy], (
                "con el destino real de la app la busqueda tiene que estar viva: "
                f"ha dado {ps.PackService._candidatos_para(PROFILES_FILE)!r}"
            )
        finally:
            ps.candidatos_de_datos = antes_candidatos
    finally:
        _t069_borrar(temp)
    print("Un data_path inyectado no arrastra la busqueda de la ruta antigua.")


def test_la_migracion_conserva_el_mtime_del_origen():
    """TASK-069 T-3. Mata al mutante `COPY_NO_COPY2` (`copy2` -> `copy`).

    `copy2` copia los metadatos y `copy` solo el contenido, asi que con `copy` el
    `profiles.json` del usuario llega al destino con la HORA DE LA COPIA. No se ve
    en el contenido, no da ningun error, y por eso es peor que una migracion
    rota: la base nueva parece correcta y es mas nueva de lo que deberia. En
    este repo la consecuencia de medir se paga en la rotacion del `.bak`, que
    decide a partir de la marca de tiempo, y en cualquier copia de seguridad que
    el usuario haga del fichero.

    La asercion mira la marca de tiempo CON VALOR FIJO: se pone con `os.utime` a
    una hora del pasado que el test declara, de modo que "no se ha copiado" y "se
    ha copiado mal" son dos resultados distinguibles y no dos finales de prueba.
    """
    import woptimizer.services.pack_service as ps
    from woptimizer.services.pack_service import PackService

    temp = tempfile.mkdtemp(prefix="wopt_t069_mtime_")
    try:
        legacy, ruta_origen = _t069_crear_legacy(temp)
        # Hora fija del pasado: 2020-01-02 03:04:05 UTC, en nanosegundos.
        fijo = 1577934245_000000000
        os.utime(ruta_origen, ns=(fijo, fijo))
        assert os.stat(ruta_origen).st_mtime_ns == fijo, "el utime del test no cuela"
        antes_candidatos = ps.candidatos_de_datos
        antes_guarda = _t069_guarda(ps)
        try:
            _t069_candidatos_que_apuntan_a(legacy, PackService)
            ruta_destino = os.path.join(temp, "destino", "profiles.json")
            svc = PackService(data_path=ruta_destino)
            assert svc.migrado_desde == legacy, (
                f"sin migracion no hay nada que medir: {svc.migrado_desde!r}"
            )
            assert os.path.exists(ruta_destino), "la migracion no creo el destino"
            mtime_destino = os.stat(ruta_destino).st_mtime_ns
            assert mtime_destino == fijo, (
                f"el destino tiene la hora {mtime_destino} y el origen la tiene "
                f"{fijo}: la copia se ha hecho con `copy` en vez de `copy2` y el "
                f"fichero del usuario ha llegado marcado como recien escrito"
            )
            assert os.stat(ruta_destino).st_size == os.stat(ruta_origen).st_size, (
                "ademas de la fecha, el contenido tiene que ser el del origen"
            )
        finally:
            _t069_restaura(ps, antes_candidatos, antes_guarda)
    finally:
        _t069_borrar(temp)
    print("La migracion copia el contenido y tambien la hora del origen.")


def test_la_degradacion_a_la_ruta_del_ejecutable_se_avisa():
    """TASK-069 T-2. Mata al mutante `DEGRADA_AL_EXE_SIN_AVISO`.

    `data_dir()` cae a `_app_dir()` cuando no hay `%APPDATA%`, ni
    `%LOCALAPPDATA%`, ni override. Eso devuelve los packs a la ruta ATADA AL
    BINARIO, que es justo la ruta que T-2 vino a quitar, y es un estado en el que
    dos instalaciones distintas se vuelven a separar los packs sin que nadie se
    entere. El codigo lo avisa, y el aviso no lo miraba nadie: MEDIDO, quitar el
    `logger.warning` de esa rama pasa los 173 tests de este ciclo.

    La asercion no es "ha fleeting un warning" sino que el aviso diga LAS DOS
    COSAS QUE LO HACEN ACCIONABLE: la variable de entorno que se ha buscado y la
    ruta a la que se ha caido, con su valor real. Un aviso generico ("no hay
    APPDATA, usando la ruta por defecto") deja al usuario sin poder arreglarlo.
    """
    import woptimizer.config as config

    temp = tempfile.mkdtemp(prefix="wopt_t069_degradacion_")
    try:
        entorno = {k: os.environ.pop(k, None)
                   for k in (config.ENV_DATA_DIR, "APPDATA", "LOCALAPPDATA")}
        try:
            with _t069_registros() as registros:
                destino = config.data_dir()
        finally:
            for clave, valor in entorno.items():
                if valor is not None:
                    os.environ[clave] = valor
        assert destino == config._app_dir(), (
            f"sin %APPDATA% la degradacion es a _app_dir() y ha salido {destino!r}"
        )
        filas = [r.getMessage() for r in registros
                 if r.funcName == "data_dir" and r.levelname == "WARNING"]
        assert len(filas) == 1, (
            f"la degradacion tiene que emitir UN aviso y ha emitido {len(filas)}: "
            f"{filas}"
        )
        aviso = filas[0]
        assert config.ENV_DATA_DIR in aviso, (
            f"el aviso no dice que variable se ha buscado, asi que el usuario no "
            f"sabe que puede poner: {aviso!r}"
        )
        assert config._app_dir() in aviso, (
            f"el aviso no dice DONDE han caído los datos, que es lo unico que "
            f"hace falta para recuperarlos: {aviso!r}"
        )
        assert os.path.basename(config._app_dir()) in aviso, (
            f"el aviso deberia pouvoir la ruta en su forma legible: {aviso!r}"
        )
    finally:
        _t069_borrar(temp)
    print("Degradar a la ruta del ejecutable se dice, con la ruta y la variable.")


def test_la_ruta_que_anuncia_el_diagnostico_existe_de_verdad():
    """TASK-069 T-1. Mata a los mutantes `T1_AVISA_RUTA_EQUIVOCADA` y
    `LOG_NOMBRA_RUTA_EQUIVOCADA`.

    Defecto REAL en HEAD, no hipotetico: la fila de T-1 concatenaba el
    directorio del candidato con el nombre del fichero SIN separador y decia
    "...\\legacyprofiles.json", una ruta que no existe. MEDIDO: el defecto no se
    ve solo porque la asercion anterior leia el log ENTERO, y la fila hermana de
    `_migrar_desde()` nombra el mismo fichero bien escrito; o sea, cinco tests
    pasaban con la fila de diagnostico rota. Un aviso que manda al usuario a una
    ruta que no lleva a ninguna parte es PEOR que no avisar, porque pierde la
    confianza en el aviso y el usuario no vuelve a mirar el siguiente.

    POR QUE se mira el REGISTRO y no el fichero de log: para que la asercion la
    satisfaga LA FILA DE DIAGNOSTICO y no cualquier otra del mismo fichero de log.
    Y el contenido se afirma en dos niveles: la ruta exacta que se nombra
    (`os.path.join(legacy, "profiles.json")`) y que esa ruta EXISTA, que es lo que
    distingue la fila bien escrita de la concatenada. La contraprueba final
    afirma que la ruta de la concatenacion NO existe, o sea que la comprobacion de
    existencia discrimina de verdad y no acepta cualquier cadena.
    """
    import woptimizer.services.pack_service as ps
    from woptimizer.services.pack_service import PackService

    temp = tempfile.mkdtemp(prefix="wopt_t069_ruta_")
    try:
        legacy, ruta_origen = _t069_crear_legacy(temp)
        antes_candidatos = ps.candidatos_de_datos
        antes_guarda = _t069_guarda(ps)
        try:
            _t069_candidatos_que_apuntan_a(legacy, PackService)
            ruta_destino = os.path.join(temp, "destino", "profiles.json")
            with _t069_registros() as registros:
                PackService(data_path=ruta_destino)
            filas = _t069_filas_de(registros, "_diagnosticar_y_migrar")
            assert len(filas) == 1, (
                f"la fila de diagnostico tiene que emitir UN aviso y ha emitido "
                f"{len(filas)}: {filas}"
            )
            aviso = filas[0]
            buena = os.path.join(legacy, "profiles.json")
            assert buena in aviso, (
                f"el aviso tiene que nombrar la ruta REAL del candidato. Dice "
                f"{aviso!r} y la ruta buena es {buena!r}"
            )
            mal = f"{legacy}profiles.json"
            assert mal not in aviso, (
                f"el aviso nombra la ruta concatenada SIN separador {mal!r}, que "
                f"no existe en ningun sitio"
            )
            assert os.path.exists(buena), "el fichero del origen no esta"
            assert not os.path.exists(mal), (
                f"CONTRAPRUEBA rota: {mal!r} deberia ser una ruta imposible, y "
                f"existe. Si existe, la comprobacion de existencia de este test "
                f"no distingue la concatenacion de la ruta buena y este test no "
                f"mide nada."
            )
            # Y la asercion de verdad: de lo que el aviso nombra, existe.
            import re
            # El punto de "profiles.json" es PARTE de la ruta, asi que el patron
            # no puede cortar en el: `[^\\s.;]+` partia el path en "profiles" y la
            # comprobacion de existencia miraba un fichero que no existe nunca.
            # Y el separador de frase es ". " (punto y espacio), que es lo unico
            # que cierra un token con seguridad: `[^\s]` partia el path en un
            # `%TEMP%` CON ESPACIOS, que es un host legitimo. MEDIDO aqui con el
            # temporal sin espacios; el patron se escribe para que tambien
            # funcione con ellos, y `\.$` cierra el ultimo.
            nombradas = re.findall(r"[A-Za-z]:[\\/].*?(?=\. |\.?$)", aviso)
            assert nombradas, f"el aviso no nombra ninguna ruta absoluta: {aviso!r}"
            for nombrada in nombradas:
                assert os.path.exists(nombrada), (
                    f"el aviso manda al usuario a {nombrada!r} y ese path no "
                    f"existe. Lo que se ofrece como ayuda tiene que estar ahi."
                )

            # Y LA FILA HERMANA, que es la MISMA clase de defecto y la que toca
            # el mutante `LOG_NOMBRA_RUTA_EQUIVOCADA`. MEDIDO, y por eso esta
            # fila existe con la forma que tiene: una version del mutante que
            # rompia la RUTA de LECTURA moria con `FileNotFoundError`, y una
            # excepcion no es una asercion del contrato sino el sintoma de un
            # mutante mal construido. El mutante de verdad nombra un path que SI
            # existe y que NO es el origen --el directorio en vez del fichero--.
            #
            # Y POR QUE LA ASERCION MIRA LA COLA DEL MENSAJE y no "la ruta buena
            # aparece en el mensaje": MEDIDO, con el mutante puesto la ruta buena
            # SEGUIA apareciendo en la otra mitad de la frase ("Packs migrados
            # por COPIA desde {origen} a ..."), luego la asercion la satisfacia
            # la mitad que el mutante no tocaba y el test pasaba en verde. La
            # cola que va detras de "EL ORIGINAL SE QUEDA en " es la que dice
            # donde se ha quedado el original, y esa no la puede satisfacer
            # nadie mas.
            filas_mig = _t069_filas_de(registros, "_migrar_desde")
            assert len(filas_mig) == 1, (
                f"la fila de la migracion tiene que emitir UN aviso y ha emitido "
                f"{len(filas_mig)}: {filas_mig}"
            )
            # El marcador se busca SIN la "El" del principio porque en el codigo
            # la frase se parte entre dos literales y la "El" queda en el
            # anterior: MEDIDO, buscarla con "EL ORIGINAL" hacia fallar el test
            # en verde, o sea un guard que no miraba nada.
            assert "ORIGINAL SE QUEDA en " in filas_mig[0], (
                f"la fila de la migracion tiene que decir donde se queda el "
                f"ORIGEN: {filas_mig[0]!r}"
            )
            cola = filas_mig[0].split("ORIGINAL SE QUEDA en ", 1)[1]
            assert cola.startswith(buena), (
                f"lo que dice que se queda el original es {cola[:90]!r} y el "
                f"origen es {buena!r}. Nombrar el DIRECTORIO en vez del fichero "
                f"manda al usuario a una carpeta y le hace buscar dentro a mano."
            )
            assert os.path.isfile(buena), (
                f"lo que dice que se queda es un FICHERO y {buena!r} no lo es"
            )
            assert ruta_destino in filas_mig[0], (
                f"la fila de la migracion tiene que decir a donde se ha copiado, "
                f"que es {ruta_destino!r}. Dice {filas_mig[0]!r}"
            )
        finally:
            _t069_restaura(ps, antes_candidatos, antes_guarda)
    finally:
        _t069_borrar(temp)
    print("La ruta que anuncia el diagnostico existe y esta escrita con separador.")


def test_el_log_de_t1_nombra_el_destino_y_el_candidato():
    """TASK-069 T-1. Mata al mutante `LOG_MUDA` (bajar la fila a un aviso
    generico).

    El criterio de T-1, escrito en la especificacion, es que el log nombre al
    CANDIDATO con su ruta absoluta: eso es lo que convierte "no encuentro tus
    packs" en algo accionable. Ese criterio no tenia guardian, y MEDIDO: bajar
    la fila a "Hay packs en otra carpeta; se van a recuperar" pasa los 173
    tests, porque ninguna asercion exigia que la fila dijera el QUÉ y el DÓNDE.

    Las dos rutas, las dos en la MISMA fila de la MISMA funcion, y por eso el
    filtro es por `funcName`: con la fila bajada, `_migrar_desde()` sigue
    nombrando el origen y un test que leyera el log entero pasaria en verde.
    """
    import woptimizer.services.pack_service as ps
    from woptimizer.services.pack_service import PackService

    temp = tempfile.mkdtemp(prefix="wopt_t069_logt1_")
    try:
        legacy, ruta_origen = _t069_crear_legacy(temp)
        antes_candidatos = ps.candidatos_de_datos
        antes_guarda = _t069_guarda(ps)
        try:
            _t069_candidatos_que_apuntan_a(legacy, PackService)
            ruta_destino = os.path.join(temp, "destino", "profiles.json")
            with _t069_registros() as registros:
                PackService(data_path=ruta_destino)
            filas = _t069_filas_de(registros, "_diagnosticar_y_migrar")
            assert len(filas) == 1, f"filas de diagnostico: {filas}"
            aviso = filas[0]
            assert ruta_destino in aviso, (
                f"el aviso tiene que decir DONDE no se han encontrado los packs "
                f"({ruta_destino!r}), que es el dato que distingue 'no estan' de "
                f"'no los he buscado'. Dice {aviso!r}"
            )
            assert os.path.join(legacy, "profiles.json") in aviso, (
                f"el aviso tiene que decir DONDE estan ({legacy}), con la ruta "
                f"absoluta del fichero y no el nombre de la carpeta. Dice "
                f"{aviso!r}"
            )
            assert os.path.isabs(os.path.join(legacy, "profiles.json")), (
                "la ruta del candidato tiene que ser absoluta: una relativa no "
                "sirve para que el usuario la encuentre"
            )
            assert aviso.count(os.sep) > 1, (
                f"un aviso de una frase sin separadores no trae ninguna ruta: "
                f"{aviso!r}"
            )
        finally:
            _t069_restaura(ps, antes_candidatos, antes_guarda)
    finally:
        _t069_borrar(temp)
    print("La fila de T-1 dice las dos rutas: donde faltan y donde estan.")


def test_el_gaming_repuesto_a_ciegas_no_es_silencioso():
    """TASK-069 T-4, y es el fallo MEDIDO que la guarda de `_candidatos_para`
    estaba causando. No lo mata ningun mutante de este turno: es el precio de
    dejar la guarda puesta, y el precio se paga aqui o no se paga.

    MEDIDO con la guarda puesta y sin esta rama: con un `data_path` inyectado
    -- o sea un destino que NO es el de la app, con la busqueda de la ruta
    antigua apagada por construccion -- el servicio llega a
    `_ensure_gaming_pack()`, repone el Gaming de FABRICA con sus 5 categorias y
    sus 2 keepers, y `mensaje_danado()` devuelve `None`. Cero diagnostico para un
    Gaming de fabrica que el usuario no eligio, que es exactamente el fallo que
    T-4 vino a cerrar por el otro lado (TASK-063: la lista anti-brick que
    desaparecia en silencio).

    Y NO se resuelve avisando siempre, porque entonces la instalacion limpia
    --el caso legitimo y mayoritario-- avisaria de un problema que no tiene. La
    contraprueba de abajo afirma que en la instalacion limpia, con la busqueda
    ENCENDIDA y sin nada que encontrar, sigue sin decirse nada.
    """
    import woptimizer.services.pack_service as ps
    from woptimizer.services.pack_service import PackService, DEFAULT_GAMING_PACK

    temp = tempfile.mkdtemp(prefix="wopt_t069_ciegas_")
    try:
        # La guarda REAL: `candidatos` queda vacio sin tocar nada.
        ruta_destino = os.path.join(temp, "inyectado", "profiles.json")
        svc = PackService(data_path=ruta_destino)
        assert svc.candidatos == [], (
            f"este test mide el estado de la guarda puesta y hay "
            f"{svc.candidatos!r} candidatos"
        )
        assert svc.gaming_repuesto is True, (
            "sin fichero, el Gaming de fabrica se repone (T-4)"
        )
        gaming = svc.get_all_packs()["gaming"]
        assert gaming.target_categories == DEFAULT_GAMING_PACK.target_categories, (
            "lo que se repone es el Gaming de fabrica, con sus categorias"
        )
        assert gaming.keepers == DEFAULT_GAMING_PACK.keepers, (
            "y con sus keepers, que son los que deciden que se apaga"
        )
        mensaje = svc.mensaje_danado()
        assert mensaje, (
            "el Gaming de fabrica se ha reponido y nadie lo va a decir: "
            "mensaje_danado() es None. Un Gaming de fabrica en silencio es el "
            "mismo fallo de seguridad que la lista anti-brick que se perdia sin "
            "avisar, y por eso T-4 lo declara"
        )
        assert ruta_destino in mensaje, (
            f"el mensaje tiene que nombrar el fichero vacio, que es lo que el "
            f"usuario puede rellenar o revisar: {mensaje!r}"
        )
        assert svc.motivo_gaming_repuesto in mensaje, (
            f"el mensaje tiene que llevar el MOTIVO declarado, que es lo que "
            f"nombra las categorias y los keepers repuestos, y no solo que "
            f"falta el fichero: {mensaje!r}"
        )
        assert f"{len(DEFAULT_GAMING_PACK.target_categories)} categorias" in mensaje, (
            f"el mensaje tiene que decir CON CUANTAS categorias, que es lo que "
            f"explica que el modo se cierre de mas: {mensaje!r}"
        )

        # CONTRAPRUEBA: instalacion limpia, con la busqueda ENCENDIDA. Aqui el
        # `None` es lo correcto y es lo que mata al mutante `SIEMPRE_AVISAR`.
        antes_guarda = _t069_guarda(ps)
        try:
            vacio = os.path.join(temp, "vacio")
            os.makedirs(vacio, exist_ok=True)
            ps.PackService._candidatos_para = staticmethod(lambda data_path: [vacio])
            limpio = PackService(data_path=os.path.join(temp, "limpio", "profiles.json"))
            assert limpio.gaming_repuesto is True, "tambien se repone al arrancar"
            assert limpio.mensaje_danado() is None, (
                f"una instalacion LIMPIA no tiene nada que contar y esta "
                f"diciendo {limpio.mensaje_danado()!r}: se ha buscado en la ruta "
                f"antigua y no habia nada, que es lo que el producto promete en su "
                f"primera ejecucion"
            )
        finally:
            _t069_restaura(ps, None, antes_guarda)
    finally:
        _t069_borrar(temp)
    print("Un Gaming repuesto a ciegas se declara; una instalacion limpia no avisa.")


def test_los_nombres_del_servicio_son_los_de_config():
    """TASK-069 T-3, cierre del cierre. Mata al mutante que vuelva a meter una
    COPIA local de la decision o un envoltorio propio alrededor de ella.

    El comentario que este test viene a sustituir afirmaba que la forma
    `from woptimizer.config import (a, b, c, d, e)` FALLA en este interprete
    cuando `services/pack_service.py` esta presente, y lo sostenia con una
    medicion. MEDIDO de nuevo: no se reproduce (CPython 3.13.8), y la linea 9 de
    este mismo fichero -- 25 lineas por encima de aquel comentario -- ya usaba
    ESA forma con tres nombres y nunca fallo. El `importlib` se ha ido porque era
    un rodeo para un bug que no existe, y no porque fuera incorrecto: ligaba el
    MISMO objeto funcion.

    Y este test ata lo que de verdad importa del asunto, que no es el rodeo sino
    la IDENTIDAD: el servicio usa la MISMA funcion que el contrato, no una copia
    suya. Si alguien reintroduce un envoltorio -- "por seguridad", "por no tocar
    config" -- la decision de que ruta manda y la del diagnostico pueden
    discrepar, y esa clase de discrepancia es invisible hasta que un usuario
    pierde packs.
    """
    import woptimizer.config as config
    import woptimizer.services.pack_service as ps

    for nombre in ("PROFILES_FILE", "PROFILES_FILE_NAME",
                   "candidatos_de_datos", "elegir_ruta_de_datos"):
        assert getattr(ps, nombre) is getattr(config, nombre), (
            f"pack_service.{nombre} no es el MISMO objeto que config.{nombre}. "
            f"El servicio tiene que usar la funcion del contrato, no una copia "
            f"local: dos copias pueden discrepar sobre que ruta manda y esa "
            f"discrepancia no se ve hasta que alguien pierde packs"
        )


def test_el_contrato_de_persistencia_se_declara_como_contrato():
    """TASK-069 T-2, cierre. Mata a los mutantes `DOC_AMILLA_MIENTRAS_DICE_APPDATA`
    y `DOC_APPDATA_EN_ARCHITECTURA_SOLO`.

    EL GUARD ANTERIOR ERA POR SUBCADENA, y por eso no mordia: quitaba la unica
    mencion de `%APPDATA%`, si, pero reescribir la frase del contrato a "junto al
    ejecutable" y dejar una mencion decorativa de `%APPDATA%` mas abajo pasaba
    los 173. Un guard que busca una cadena en un documento que el mutante puede
    dejar puesta en otro parrafo no vigila el contrato: vigila la cadena.

    EL PREDICADO es de CONTENIDO y exige que las dos mitades del contrato esten en
    la MISMAunidad de texto: la ruta `%APPDATA%\\woptimizer\\profiles.json` Y la
    negacion de "junto al ejecutable". Con las dos dentro del mismo parrafo se cae
    a la vez la mencion decorativa y la frase reescrita, y ninguna de las dos
    puede sustituir a la otra.

    Y, que es lo que el guard anterior no hacia: el mutante PASA POR EL GUARD. Se
    escribe el documento mutado a `%TEMP%`, se LEE DE NUEVO y se le pasa al
    MISMO predicado que usa el validador, y se exige que lo acuse. Un guard que
    devuelve siempre lista vacia no puede pasar esto porque la contraprueba es el
    documento real mutado, no una cadena en memoria.
    """
    import validate_docs

    root = os.path.dirname(os.path.abspath(__file__))
    docs = ("architecture.md", "data-models.md")
    predicado = validate_docs.violaciones_del_contrato_de_persistencia

    for nombre in docs:
        with open(os.path.join(root, "docs", "ai", nombre), encoding="utf-8") as fh:
            cuerpo = fh.read()
        assert predicado(cuerpo, nombre) == [], (
            f"{nombre} declara el contrato de persistencia y el predicado lo "
            f"acusa: {predicado(cuerpo, nombre)}"
        )

    temp = tempfile.mkdtemp(prefix="wopt_t069_contrato_")
    try:
        with open(os.path.join(root, "docs", "ai", "data-models.md"),
                  encoding="utf-8") as fh:
            base = fh.read()

        # MUTANTE 1: la frase del contrato pasa a decir "junto al ejecutable" y se
        # AÑADE una mencion DECORATIVA de `%APPDATA%` mas abajo, que es lo que
        # hacia pasar el guard por subcadena. La mencion se añade de verdad
        # (append) y no se cambia por otra: en `data-models.md` el unico sitio
        # donde se nombra `%APPDATA%` es la propia frase del contrato, asi que un
        # mutante "realista" tiene que dejar la cadena puesta en otra parte.
        m1 = base.replace(
            "el archivo en disco es `%APPDATA%\\woptimizer\\profiles.json`, y ya NO\n"
            "  está junto al ejecutable.",
            "el archivo en disco vive junto al ejecutable.")
        m1 = m1 + ("\n- Nota de entorno de este host: `%APPDATA%` apunta a la carpeta de\n"
                   "  Roaming del usuario y aqui solo se menciona de pasada.\n")
        # El pre-vuelo mira la FRASE DEL CONTRATO y no la ruta a secas. MEDIDO en
        # esta misma pasada: la ruta `%APPDATA%\woptimizer\profiles.json` sale
        # tambien en la fila de la precedencia, que esta dos parrafos mas abajo, y
        # un pre-vuelo que exigiera "la ruta no aparece" moria con el mutante
        # CORRECTAMENTE aplicado. Un pre-vuelo que no distingue es un pre-vuelo
        # que obliga a aflojar la asercion buena.
        assert "y ya NO\n  está junto al ejecutable" not in m1, (
            "el mutante 1 tiene que quitar la NEGACION de la frase del contrato, y "
            "el remplazo no ha aplicado: la prueba de que el mutante es lo que dice "
            "no vale"
        )
        assert "el archivo en disco vive junto al ejecutable" in m1, (
            "el mutante 1 tiene que reescribir la frase del contrato a 'junto al "
            "ejecutable', y el remplazo no ha aplicado"
        )
        ruta_m1 = os.path.join(temp, "data-models-mutado-1.md")
        with open(ruta_m1, "w", encoding="utf-8") as fh:
            fh.write(m1)
        with open(ruta_m1, encoding="utf-8", newline="") as fh:
            leido = fh.read()
        assert "%APPDATA%" in leido, (
            "CONTRAPRUEBA del mutante 1: la mencion decorativa tiene que seguir "
            "ahi, o el guard anterior (por subcadena) lo habria muerto y este "
            "test no estaria probando lo que dice probar"
        )
        assert predicado(leido, "data-models.md mutado 1"), (
            "un contrato reescrito a 'junto al ejecutable' con una mencion "
            "decorativa de `%APPDATA%` mas abajo tiene que ser acusado: lo que "
            "dice el documento y donde estan de verdad los datos han divergido"
        )

        # MUTANTE 2: la ruta entera se queda y se cae la NEGACION, que es la otra
        # mitad del contrato. Un guard que solo mirase la ruta pasaria.
        m2 = base.replace("y ya NO\n  está junto al ejecutable.",
                          "y además\n  está junto al ejecutable.")
        ruta_m2 = os.path.join(temp, "data-models-mutado-2.md")
        with open(ruta_m2, "w", encoding="utf-8") as fh:
            fh.write(m2)
        with open(ruta_m2, encoding="utf-8", newline="") as fh:
            leido2 = fh.read()
        assert "`%APPDATA%\\woptimizer\\profiles.json`" in leido2, (
            "el mutante 2 conserva la ruta a proposito"
        )
        assert predicado(leido2, "data-models.md mutado 2"), (
            "un contrato que dice la ruta correcta y no dice que ya NO este junto "
            "al ejecutable esta a medio camino: la mitad de la frase que evita que "
            "alguien lo vuelva a mover tiene que estar escrita"
        )
    finally:
        _t069_borrar(temp)
    print("El contrato de persistencia se comprueba por contenido, no por cadena.")


def _t069_ascii(texto):
    """`texto` sin nada fuera de cp1252, para poder imprimirlo al fallar.

    La consola de este host es cp1252 y `mensaje_danado()` lleva los emojis de
    las categorias del Gaming de fabrica. Un `assert` que imprime un emoji no
    MUERE: revienta con `UnicodeEncodeError` dentro del mensaje del fallo, y un
    fallo que se muere por la codificacion esconde el motivo real -- que es
    justo lo que un mutante necesita que no pase.
    """
    return (texto or "").encode("ascii", "replace").decode("ascii")


def test_la_rotacion_no_macha_el_bak_que_guarda_lo_unico():
    """TASK-069, ronda 2. EL HALLAZGO MAS GRAVE: la migracion se come el `.bak`
    bueno del dueño en su primer guardado. TOCA DATOS DEL USUARIO.

    EL CASO MEDIDO (C): destino inexistente, un `.bak` PREVIO del dueño con el
    pack `viejo01`, y un ORIGEN con `gaming` + 3 packs. Tras la carga el `.bak`
    sigue intacto -- la migracion es `copy2` y no toca el `.bak`. Tras el
    `save()`, el `.bak` pasa a los 4 ids de la copia y queda BYTE A BYTE igual al
    origen (sha identica), y `viejo01`, que no estaba ni en el origen ni en el
    destino, DESAPARECE sin dejar rastro.

    POR QUE ES PEOR QUE NO MIGRAR: el `.bak` es lo UNICO que el usuario tiene si
    el destino se corrompe, y la migracion lo destruia en el primer guardado que
    hiciera el usuario. La rotacion es un anillo de UNA plaza y la migracion
    mete una TERCERA generacion en un anillo de dos: el recycled tiene que
    comerse a alguien, y sin este fix se come a la copia buena del dueño.

    LO QUE SE AFIRMA, y por que cada fila discrimina:
      1. `viejo01` sigue siendo LEGIBLE despues del `save()`. La asercion es
         "existe y se puede parsear", no "existe": con el mutante que BORRA el
         fichero en vez de pisarlo, un `os.path.exists` pasaria por la razon
         equivocada. Es el mismo criterio que usa L1 de TASK-031.
      2. El contenido del rescate es el del `.bak` viejo, no el del destino: si
         el rescate copiara el principal, `viejo01` desapareceria igual.
      3. El `.bak` ANDA: la rotacion no se ha congelado. Un fix que dijera "no
         rotas nunca" dejaria al usuario sin red anti-brick para siempre, y eso
         es el fallo de seguridad de TASK-023/030 en su otra forma.
      4. El mensaje NOMBRA el fichero donde se ha dejado lo apartado, que es lo
         unico que hace que el dato serve: un rescate mudo se limpia como
         fichero de mas.

    Y LA CONTRAPRUEBA, que es lo que hace el test notrivial: con un `.bak` que
    NO guarda nada unico (el caso de todos los dias: el `.bak` es la version
    anterior, y todo lo que hay en el se relee en el destino), NO se crea
    fichero de rescate y la rotacion ocurre. Sin esta fila, "no rotar" y "crear
    un rescate por cada guardado" passerian los dos.
    """
    import json
    import woptimizer.services.pack_service as ps
    from woptimizer.services.pack_service import PackService, RESCATE_SUFFIX

    raiz = tempfile.mkdtemp(prefix="wopt069_bak_")
    try:
        # --- CASO C: el `.bak` del dueño + migracion. ---
        legacy, ruta_origen = _t069_crear_legacy(raiz)
        destino_dir = os.path.join(raiz, "datos")
        os.makedirs(destino_dir, exist_ok=True)
        destino = os.path.join(destino_dir, "profiles.json")
        bak = destino + ".bak"
        # El pack del dueño que SOLO vive en su backup.
        _t069_escribir_profiles(bak, {"packs": {
            "viejo01": {"id": "viejo01", "name": "viejo", "apps": ["viejo.exe"]}}})
        sha_bak_del_dueno = _t069_sha256(bak)
        sha_origen = _t069_sha256(ruta_origen)

        antes_cand = ps.candidatos_de_datos
        antes_guarda = _t069_guarda(ps)
        _t069_candidatos_que_apuntan_a(legacy, PackService)
        try:
            svc = PackService(data_path=destino)
        finally:
            _t069_restaura(ps, antes_cand, antes_guarda)

        # La carga sola NO toca el `.bak`: la migracion copia el origen al
        # destino y no se mete con el backup del dueño. Esta fila separa las
        # dos mitades del fallo; sin ella, un fix en la migracion que "tampoco
        # rota" y uno que "aparta" darian el mismo veredicto aqui.
        assert _t069_sha256(bak) == sha_bak_del_dueno, (
            "la carga de la migracion ya ha tocado el .bak del dueno, y el fallo "
            "no es de la rotacion sino de la copia. Sin esta fila, arreglar la "
            "mitida de la rotacion podria dejar la de la migracion viva."
        )
        assert _t069_sha256(ruta_origen) == sha_origen, "el ORIGEN se queda intacto"

        # El `save()` del usuario: el momento en el que el anillo se recycling.
        svc.save()

        with open(bak, "r", encoding="utf-8") as fh:
            bak_despues = json.load(fh)
        assert "viejo01" not in bak_despues.get("packs", {}), (
            "el .bak se ha reciclado con la copia de la migracion, que es lo que "
            "hacia ANTES del fix y lo que el reporto como el hallazgo mas grave: "
            f"quedan {sorted(bak_despues.get('packs', {}))} y `viejo01` no esta en "
            "ningun sitio del destino. El .bak es lo unico que el usuario tiene si "
            "el destino se corrompe, y la migracion lo destruia en su primer "
            "guardado."
        )
        # El origen, ademas, tiene los 3 packs: el `.bak` no los ha ganado nunca.
        with open(ruta_origen, "r", encoding="utf-8") as fh:
            assert len(json.load(fh)["packs"]) == 2, "el origen de la fixture"

        # 1. `viejo01` sigue LEGIBLE, y el unico sitio donde vive es el rescate.
        assert svc.bak_rescatado, (
            "la rotacion no ha dicho nada pese a que el .bak que iba a machacar "
            "guardaba `viejo01`, que no esta ni en el destino ni en el origen de "
            "la migracion. Estado vacio: "
            f"bak_rescatado={svc.bak_rescatado!r}"
        )
        assert svc.bak_rescatado.startswith(bak), (
            f"el rescate deberia vivir al lado del .bak y sale {svc.bak_rescatado!r}: "
            f"el prefijo esperado era {bak!r}"
        )
        assert svc.bak_rescatado.endswith(RESCATE_SUFFIX), (
            f"el rescate no lleva el sufijo declarado {RESCATE_SUFFIX!r}: "
            f"{svc.bak_rescatado!r}. Sin el, el usuario no sabe que ese fichero es "
            "suyo y lo borra como basura."
        )
        # 2. El contenido del rescate es el del `.bak` VIEJO, no del principal.
        with open(svc.bak_rescatado, "r", encoding="utf-8") as fh:
            rescatado = json.load(fh)
        assert "viejo01" in rescatado.get("packs", {}), (
            f"el rescate se ha escrito pero no contiene el pack que se iba a "
            f"perder: {sorted(rescatado.get('packs', {}))}. Un rescate del "
            "principal se lee como 'he guardado algo' y no guarda nada."
        )
        assert set(rescatado["packs"]) == {"viejo01"}, (
            "el rescate deberia ser una copia LITERAL del .bak anterior, no una "
            f"mezcla: {sorted(rescatado['packs'])}"
        )
        # 3. La rotacion ANDA: el anillo no se ha congelado.
        assert set(bak_despues.get("packs", {})) == {"gaming", "8fefbc22"}, (
            "el .bak deberia haberse reciclado con la version anterior del "
            f"principal, y hay {sorted(bak_despues.get('packs', {}))}. Un fix que "
            "dijera 'no se rota nunca' dejaria al usuario sin red anti-brick para "
            "siempre, que es el fallo de TASK-023/030 en su otra forma."
        )
        # 4. El mensaje lo dice, con la ruta.
        mensaje = _t069_ascii(svc.mensaje_danado() or "")
        assert svc.bak_rescatado in mensaje, (
            f"la generacion apartada no se nombra en el mensaje: {mensaje!r}. Un "
            "rescate mudo se limpia como fichero de mas."
        )
        assert "viejo01" in mensaje, (
            f"el mensaje no dice QUE se ha apartado: {mensaje!r}"
        )

        # --- CONTRAPRUEBA: nada unico -> no hay rescate y la rotacion ocurre. ---
        limpio = tempfile.mkdtemp(prefix="wopt069_bak_limpio_")
        try:
            destino2 = os.path.join(limpio, "profiles.json")
            svc2 = PackService(data_path=destino2)
            svc2.create_user_pack("a", "A", ["a.exe"])   # 1er save: no hay .bak
            bak2 = destino2 + ".bak"
            assert not os.path.exists(bak2), (
                f"una instalacion limpia no crea un .bak de basura: {bak2}"
            )
            svc2.create_user_pack("b", "B", ["b.exe"])   # 2o save: rota de verdad
            assert os.path.exists(bak2), "el segundo guardado tiene que rotar"
            with open(bak2, "r", encoding="utf-8") as fh:
                rotado = json.load(fh)
            assert set(rotado["packs"]) == {"gaming", "protected_apps", "a"}, (
                "la rotacion normal tiene que seguir occurrido: "
                f"{sorted(rotado['packs'])}"
            )
            assert svc2.bak_rescatado == "", (
                "se ha creado un rescate para un .bak que NO guardaba nada unico: "
                f"{svc2.bak_rescatado!r}. Con esta fila abajo, el fix seria "
                "apuntar un fichero por cada guardado del mundo."
            )
        finally:
            _t069_borrar(limpio)
    finally:
        _t069_borrar(raiz)
    print("La rotacion aparta lo unico antes de machacar el backup (C).")


def test_el_gaming_repuesto_se_declara_tambien_si_el_origen_esta_corrupto():
    """TASK-069, ronda 2, T-4bis. EL MISMO PUNTO CIEGO POR OTRA PUERTA.
    TOCA DATOS Y SEGURIDAD.

    `_ensure_gaming_pack()` se llama al FINAL de `load()`, sea cual sea la puerta,
    luego la reposicion del Gaming de FABRICA ocurre por TRES puertas. T-4
    declaraba UNA. MEDIDO: con el destino ILEGIBLE **y el ORIGEN ALSO ilegible**
    -- los dos ficheros del usuario rotos -- `gaming_repuesto` sale True con 5
    categorias y los keepers steam/discord, `mensaje_danado()` nombra la
    corrupcion y **no** la reposicion (`"gaming"/"fabrica"/"repuest"` en el
    mensaje -> False), y el `save()` siguiente deja el fichero del usuario con
    `['gaming']`: un Gaming de fabrica MAS AGRESSIVO escrito encima de su
    fichero.

    Y POR QUE EL MUTANTE DE T-4 NO LO CAZA: el mutante que mata la rama de
    mensaje de T-4 quita el `extra` de la rama de la AUSENCIA, que es otra. Este
    lo quita de la rama de la CORRUPCION, que no se miraba. Es el mismo patron
    que S7 de TASK-066 -- una regla escrita en un sitio y sin ejecutar en otro.

    LAS TRES FILAS, y la tercera es la contraprueba que hace el test no trivial:
      1. el mensaje nombra el MOTIVO de la reposicion, con sus categorias y sus
         keepers (mismo criterio que la fila de seguridad de T-4);
      2. el mensaje SIGUE nombrando la corrupcion, con su excepcion: declarar mas
         no puede ser tapar lo que ya se decia;
      3. el origen corrupto NO se repara ni se sobrescribe: cargar no escribe.
    """
    import json
    import woptimizer.services.pack_service as ps
    from woptimizer.services.pack_service import PackService, DEFAULT_GAMING_PACK

    raiz = tempfile.mkdtemp(prefix="wopt069_t4bis_")
    try:
        legacy = os.path.join(raiz, "legacy")
        os.makedirs(legacy, exist_ok=True)
        ruta_origen = os.path.join(legacy, "profiles.json")
        with open(ruta_origen, "w", encoding="utf-8") as fh:
            fh.write("{ el origen tampoco es json")
        destino = os.path.join(raiz, "datos", "profiles.json")
        os.makedirs(os.path.dirname(destino), exist_ok=True)
        with open(destino, "w", encoding="utf-8") as fh:
            fh.write('{"packs": {"a medias": ')

        antes_cand = ps.candidatos_de_datos
        antes_guarda = _t069_guarda(ps)
        _t069_candidatos_que_apuntan_a(legacy, PackService)
        try:
            svc = PackService(data_path=destino)
        finally:
            _t069_restaura(ps, antes_cand, antes_guarda)

        assert svc.gaming_repuesto is True, (
            "la mitad de la precondicion del hallazgo: si el Gaming de fabrica "
            "no se repone en este caso, este test no midiria el fallo que dice "
            "medir"
        )
        gaming = svc.get_gaming_pack()
        assert len(gaming.target_categories) == 5 and \
            sorted(gaming.keepers) == ["discord.exe", "steam.exe"], (
            "lo que se repone tiene que ser el Gaming de FABRICA, que es lo que "
            "hace el dano: mas categorias y keepers que los que el usuario eligio"
        )

        mensaje = svc.mensaje_danado() or ""
        plano = _t069_ascii(mensaje)
        # 1. La reposicion se NOMBRA. Sin esta fila el mutante pasa en verde.
        assert svc.motivo_gaming_repuesto in mensaje, (
            "el mensaje declara la corrupcion y se calla la reposicion del Gaming "
            f"de FABRICA que el proximo save() va a escribir: {plano!r}. El "
            f"motivo declarado es {plano!r} y no aparece. Un mensaje que declara "
            "una perdida y calla la otra sigue siendo un mensaje incompleto, y "
            "la otra es la de seguridad."
        )
        for keeper in ("steam.exe", "discord.exe"):
            assert keeper in mensaje, (
                f"el mensaje no nombra el keeper {keeper}: {plano!r}. La lista "
                "anti-brick es justo lo que el usuario tiene que revisar."
            )
        # 2. La corrupcion SE SIGUE nombrando. Declarar mas no es tapar lo de antes.
        assert "JSONDecodeError" in mensaje, (
            f"la rama de corrupcion ha dejado de decir QUE pasa: {plano!r}"
        )
        assert svc.motivo_danado in mensaje, (
            f"el detalle de la corrupcion no esta en el mensaje: {plano!r}"
        )
        # Y el mensaje es el de la corrupcion, no el generico del Gaming: el
        # orden de gravedad no se ha movido para que lo nuevo lo tape.
        assert "copia de seguridad" in mensaje, (
            f"esta rama deberia ser la de 'NO hay copia de seguridad legible': "
            f"{plano!r}"
        )
        # 3. Cargar NO escribe: el fichero roto del usuario se queda roto y el
        #    origen tampoco se toca, para que los pueda reparar.
        with open(destino, encoding="utf-8") as fh:
            assert fh.read() == '{"packs": {"a medias": ', (
                "la carga ha reescrito el fichero corrupto del usuario. "
                "load() es de solo lectura y el destino se queda en disco tal cual"
            )
        with open(ruta_origen, encoding="utf-8") as fh:
            assert fh.read() == "{ el origen tampoco es json", (
                "la carga ha tocado el ORIGEN, que tambien esta corrupto y es del "
                "usuario. Que este corrupto no lo convierte en un fichero que se "
                "pueda reparar"
            )
        # Y lo que el `save()` siguiente haria queda MEDIDO en el docstring del
        # hallazgo; aqui no se escribe para no perder la evidencia en disco.
        assert sorted(svc.get_all_packs()) == ["gaming", "protected_apps"], (
            "el estado en memoria con los dos ficheros rotos es el Gaming de "
            f"fabrica y nada mas: {sorted(svc.get_all_packs())}"
        )
    finally:
        _t069_borrar(raiz)
    print("El Gaming repuesto se declara tambien con el origen corrupto.")


def test_el_diagnostico_pasa_por_el_punto_unico_de_decision():
    """TASK-069, ronda 2, hallazgo 3. M4: `_diagnosticar_y_migrar()` LATERALIZA
    el punto unico de decision y la suite entera no se entera.

    `elegir_ruta_de_datos()` (`config.py`) es el UNICO sitio donde vive la regla
    de instalacion limpia y la decision de ruta de T-1/T-2, y es donde se puede
    probar la decision SIN disco. `_diagnosticar_y_migrar()` TIENE que pasar por
    ahi. MEDIDO: el mutante `M4_COPIA_LOCAL` lo ENVUELVE con su propio
    `_copia_local` y devuelve `(destino_, [])` cuando el destino es legible; la
    suite completa pasa en verde (log en `ALL TESTS PASSED.`, 105 lineas de diff
    que son ruido de Tk) y con eso cualquier cambio futuro de
    `elegir_ruta_de_datos` deja de llegar a la migracion sin que nadie lo note.

    POR QUE `ast` Y NO TEXTO, y no es purismo: `elegir_ruta_de_datos` aparece
    tambien en el DOCSTRING de `_diagnosticar_y_migrar()` -- de ahi viene el
    nombre -- asi que un `inspect.getsource(...)` con un `in` lo daria por
    GOOD. Un comentario no ejecuta nada. Es la misma clase que
    `CONTRATO_SIN_CABLEAR` de TASK-069, que medico justo asi: el nombre estaba
    en la prosa y el mutante que borraba la LLAMADA sobrevivio.

    Y POR QUE HACE FALTA ADEMAS DEL COMPORTAMIENTO: un test de contenido ("con el
    destino legible no se migra") NO lo mata, porque la copia local decide lo
    MISMO que la original en el caso que se puede observar; lo que la delata es
    que la decision ha dejado de pasar por el sitio unico.
    """
    import ast
    import inspect
    import textwrap
    from woptimizer.services.pack_service import PackService

    def llamadas_de(fn):
        """Los NOMBRES de funcion a los que `fn` llama DE VERDAD, sin prosa."""
        arbol = ast.parse(textwrap.dedent(inspect.getsource(fn)))
        return {n.func.id for n in ast.walk(arbol)
                if isinstance(n, ast.Call) and isinstance(n.func, ast.Name)}

    cableo = llamadas_de(PackService._diagnosticar_y_migrar)
    assert "elegir_ruta_de_datos" in cableo, (
        "el diagnostico tiene que CALLAR a elegir_ruta_de_datos(), que es el punto "
        f"unico donde vive la regla de instalacion limpia y la decision de ruta: "
        f"las llamadas reales de _diagnosticar_y_migrar son {sorted(cableo)}. Con "
        "una copia local dentro, cualquier cambio futuro de la decision deja de "
        "llegar a la migracion y la suite sigue en verde: M4_COPIA_LOCAL medido."
    )
    # Y el diagnostico no puede decidir el destino por su cuenta: si además se
    # define `_copia_local`, es la sombra de la decision, y el mutante la trae.
    fuente = textwrap.dedent(inspect.getsource(PackService._diagnosticar_y_migrar))
    assert "_copia_local" not in fuente, (
        "_diagnosticar_y_migrar() se ha definido su PROPIA copia de la decision. "
        "Dosimplementaciones de 'que ruta gano' no pueden coexistir: la segunda "
        "no la vigila nadie y la suite no se entera"
    )
    print("El diagnostico pasa por el punto unico de decision (M4).")


def test_el_destino_que_gana_tiene_que_decir_que_hay_packs_que_no_vienen():
    """TASK-069, ronda 2, hallazgos 4 y 5. LA PRECEDENCIA ES CORRECTA Y ESTA
    ESCRITA; lo que no estaba escrita era su CONSECUENCIA, y toca datos.

    MEDIDO por el auditor y MEDIDO aqui de nuevo, con las DOS combinaciones que
    la precedencia escrita no nombraba:

      * destino legible y VACIO (`{"packs": {}}`) + origen con 3 packs: gana el
        destino, no se copia nada, `migrado_desde` y `packs_en_otra_ruta` salen
        vacios, `fichero_danado` es False y el mensaje era el del Gaming. Los 3
        packs heredados NO VUELVEN y NADIE LO DIJE, y el `save()` siguiente
        dejaba el destino con `['gaming']`: un Gaming de FABRICA mas agresivo
        escrito encima de un fichero que ya existia y era del usuario;
      * destino legible con 1 pack + origen con 3: gana IGUAL. La precedencia
        es ESTRICTA -- el numero de packs NO entra, no fusiona y no gana el que
        tiene mas -- y antes de este test eso no lo decia ni el log.

    LO QUE SE AFIRMA, y por que discrimina:
      1. la PRECEDENCIA se respeta (el destino gana, no se copia, no se
         fusiona, el origen queda intacto): es el guardian de TASK-069 y no se
         toca;
      2. el mensaje NOMBRA la ruta del origen con los packs que no han venido,
         y CUANTOS son, y son los que de verdad faltan. Un aviso que dijera
         "hay packs en otra ruta" sin decir cuales seria el mismo silencio con
         prosa;
      3. el mensaje NO inventa una perdida cuando no la hay: la contraprueba
         con el destino teniendo todos los ids del origen tiene que dar
         `mensaje_danado() is None`. Sin esta fila, "avisar siempre" seria un
         arreglo que avisa de un problema inexistente en cada arranque con la
         1.0.0 todavia en el disco.

    Y LO QUE ESTE TEST NO DECIDE: si esos packs deben VOLVER. Es una pregunta de
    producto para el dueno, escrita en `docs/ai/data-models.md` con sus tres
    opciones. Aqui solo se fija que la decision no se lleva en silencio.
    """
    import json
    import woptimizer.services.pack_service as ps
    from woptimizer.services.pack_service import PackService

    raiz = tempfile.mkdtemp(prefix="wopt069_precio_")
    try:
        legacy, ruta_origen = _t069_crear_legacy(raiz)
        sha_origen = _t069_sha256(ruta_origen)
        ids_origen = sorted(json.load(open(ruta_origen, encoding="utf-8"))["packs"])
        antes_cand = ps.candidatos_de_datos
        antes_guarda = _t069_guarda(ps)
        _t069_candidatos_que_apuntan_a(legacy, PackService)
        try:
            # --- FILA 1: destino EXISTENTE y VACIO. Gana, y no hay nada que decir
            #     de la precedencia; lo que hay que decir es el PRECIO. ---
            vacio = os.path.join(raiz, "datos", "profiles.json")
            os.makedirs(os.path.dirname(vacio), exist_ok=True)
            with open(vacio, "w", encoding="utf-8") as fh:
                json.dump({"packs": {}}, fh, indent=4)
            sha_vacio = _t069_sha256(vacio)
            svc = PackService(data_path=vacio)
            assert sorted(svc.get_all_packs()) == ["gaming", "protected_apps"], (
                f"con el destino vacio lo unico que hay es el Gaming: "
                f"{sorted(svc.get_all_packs())}"
            )
            assert svc.fichero_danado is False and svc.migrado_desde == "", (
                "un destino legible y vacio NO esta corrupto y no ha migrated: "
                f"fichero_danado={svc.fichero_danado} "
                f"migrado_desde={svc.migrado_desde!r}"
            )
            assert _t069_sha256(vacio) == sha_vacio, (
                "la carga ha reescrito el destino vacio del usuario"
            )
            mensaje = _t069_ascii(svc.mensaje_danado() or "")
            assert legacy in mensaje, (
                "el destino ha ganado por precedencia y hay packs en el origen, y "
                f"el mensaje no nombra esa ruta: {mensaje!r}. Los 3 packs "
                "heredados no vuelven y el usuario se entera por la via de que no "
                "estan."
            )
            for falta in ids_origen:
                if falta == "gaming":
                    continue    # el destino ya tiene un gaming, el suyo no
                assert falta in mensaje, (
                    f"el mensaje no nombra el pack {falta!r} que solo vive en el "
                    f"origen: {mensaje!r}. Un aviso que dice 'hay packs en otra "
                    "ruta' sin decir cuales es el mismo silencio con prosa."
                )
            assert svc.motivo_gaming_repuesto in (svc.mensaje_danado() or ""), (
                "el destino vacio dispara la reposicion del Gaming de FABRICA y "
                "el mensaje no la declara: son dos perdidas en el mismo arranque"
            )
            assert _t069_sha256(ruta_origen) == sha_origen, (
                "el ORIGEN se ha tocado: es de solo lectura aqui"
            )

            # --- FILA 2: el destino tiene MENOS packs que el origen. Gana igual,
            #     porque la precedencia es estricta. ---
            hoy = os.path.join(raiz, "datos2", "profiles.json")
            packs_hoy = _t069_packs_del_usuario_hoy()
            _t069_escribir_profiles(hoy, packs_hoy)
            sha_hoy = _t069_sha256(hoy)
            svc2 = PackService(data_path=hoy)
            assert sorted(svc2.get_all_packs()) == ["gaming", "protected_apps", "reciente"], (
                "con el destino legible gana el destino aunque traiga menos packs: "
                f"{sorted(svc2.get_all_packs())}"
            )
            assert svc2.packs_solo_en_el_origen == legacy, (
                "el servicio tiene que saber que hay packs que no han venido y no "
                f"lo ha anotado: packs_solo_en_el_origen={svc2.packs_solo_en_el_origen!r}"
            )
            assert svc2.packs_que_no_han_venido == {"8fefbc22"}, (
                f"tiene, y salen {sorted(svc2.packs_que_no_han_venido)}"
            )
            mensaje2 = _t069_ascii(svc2.mensaje_danado() or "")
            assert "8fefbc22" in mensaje2 and legacy in mensaje2, (
                f"el mensaje no dice que pack ni de donde: {mensaje2!r}"
            )
            assert _t069_sha256(hoy) == sha_hoy, (
                "la carga ha reescrito el destino del usuario con la precedencia"
            )

            # --- FILA 2b: el caso que hace DISCRIMINABLE el mutante
            #     `PRECEDENCIA_POR_NUMERO`, y por eso lleva un origen de TRES
            #     packs contra un destino de DOS. Con el origen de dos y el
            #     destino de dos, "gana el que tiene mas" y "gana el destino"
            #     dan el MISMO resultado y el mutante pasa: una fila que no
            #     separa las dos reglas no vigila ninguna.
            legacy3 = os.path.join(raiz, "legacy3")
            os.makedirs(legacy3, exist_ok=True)
            ruta_origen3 = os.path.join(legacy3, "profiles.json")
            _t069_escribir_profiles(ruta_origen3, {"packs": dict(
                _t069_profiles_v1_0_0()["packs"],
                extra={"id": "extra", "name": "extra", "apps": ["extra.exe"]})})
            sha_origen3 = _t069_sha256(ruta_origen3)
            _t069_candidatos_que_apuntan_a(legacy3, PackService)
            dos = os.path.join(raiz, "datos2b", "profiles.json")
            _t069_escribir_profiles(dos, _t069_packs_del_usuario_hoy())
            svc2b = PackService(data_path=dos)
            assert sorted(svc2b.get_all_packs()) == ["gaming", "protected_apps", "reciente"], (
                "con un destino de DOS packs y un origen de TRES gana el destino: "
                f"la precedencia es ESTRICTA y el numero de packs NO entra. Han "
                f"saliendo {sorted(svc2b.get_all_packs())}, que es lo que haria un "
                "'gana el que tiene mas' o una fusion silenciosa"
            )
            assert sorted(svc2b.packs_que_no_han_venido) == ["8fefbc22", "extra"], (
                "los packs que solo viven en el origen son los que el destino no "
                f"tiene: {sorted(svc2b.packs_que_no_han_venido)}"
            )
            assert _t069_sha256(ruta_origen3) == sha_origen3, (
                "el ORIGEN se ha tocado al DECLARAR que sus packs no han venido: "
                "anotar no es migrar"
            )
            _t069_candidatos_que_apuntan_a(legacy, PackService)

            # --- FILA 3: CONTRAPRUEBA. El destino tiene TODO lo del origen: no
            #     hay packs que no vengan y no se dice nada. ---
            completo = os.path.join(raiz, "datos3", "profiles.json")
            _t069_escribir_profiles(completo, {"packs": {
                "gaming": packs_hoy["packs"]["gaming"],
                "8fefbc22": {"id": "8fefbc22", "name": "sync", "apps": ["x.exe"]},
            }})
            svc3 = PackService(data_path=completo)
            assert svc3.packs_solo_en_el_origen == "", (
                "el destino tiene todos los ids del origen y aun así se ha "
                f"anotado: {svc3.packs_solo_en_el_origen!r}"
            )
            assert svc3.mensaje_danado() is None, (
                "no hay ninguna perdida que contar y se avisa: "
                f"{_t069_ascii(svc3.mensaje_danado() or '')!r}. Un aviso por "
                "arranque seria peor que el silencio que venia."
            )
        finally:
            _t069_restaura(ps, antes_cand, antes_guarda)
    finally:
        _t069_borrar(raiz)
    print("El destino que gana dice lo que deja fuera (4 y 5).")


def test_el_check_del_contrato_usa_el_mismo_predicado_que_el_test():
    """TASK-069 T-2, cierre. Mata al mutante que deje el predicado en
    `run_tests.py` y no lo cablee en `validate_docs.py`.

    MEDIDO: hasta este cierre el guard vivia SOLO en `run_tests.py`, y
    `validate_docs.py` no tenia ninguno de TASK-069. O sea que un documento
    reescrito se sostenia en verde mientras la suite corriera y caia en rojo
    cuando no corriera: al reves de como funciona una guarda.

    Y la atadura se afirma por AST, no por TEXTO, y no es purismo. MEDIDO en esta
    misma ronda: la primera version de esta fila buscaba el nombre del predicado
    con `inspect.getsource(validar)` y el mutante `CONTRATO_SIN_CABLEAR` --que
    borra la LLAMADA-- **sobrevivio**, porque el nombre del predicado esta
    tambien en el COMENTARIO que explica por que se delega, y un comentario no
    ejecuta nada. Es la misma clase que el superviviente S7 de TASK-066 ("la
    regla de rama escrita en un comentario"), y este repo ya lo pago una vez.
    """
    import ast
    import inspect
    import textwrap
    import validate_docs

    def llamadas_de(fn):
        """Los NOMBRES de funcion a los que `fn` llama DE VERDAD, sin prosa.

        `inspect.getsource` + un `in` no distinguen codigo de comentario, y `ast`
        si: un comentario no es un nodo `ast.Call`.
        """
        arbol = ast.parse(textwrap.dedent(inspect.getsource(fn)))
        return {n.func.id for n in ast.walk(arbol)
                if isinstance(n, ast.Call) and isinstance(n.func, ast.Name)}

    cableo = llamadas_de(validate_docs.validar)
    assert "_comprobar_contrato_de_persistencia" in cableo, (
        "el check del contrato tiene que estar CALLADO en validar(), no "
        f"mencionado: las llamadas reales de validar() son {sorted(cableo)}. Un "
        "check que solo aparece en un comentario no se ejecuta cuando nadie "
        "mira el comentario."
    )
    dentro = llamadas_de(validate_docs._comprobar_contrato_de_persistencia)
    assert "violaciones_del_contrato_de_persistencia" in dentro, (
        "el check tiene que CALLAR al predicado que este test usa, y sus "
        f"llamadas reales son {sorted(dentro)}"
    )
    # Y el predicado tiene que ser el MISMO OBJETO, no uno con el mismo nombre.
    assert (validate_docs._comprobar_contrato_de_persistencia.__module__
            == validate_docs.violaciones_del_contrato_de_persistencia.__module__), (
        "el predicado que usa el validador y el que usa este test tienen que "
        "salir del MISMO modulo"
    )
    # Los DOS documentos se nombran en la FUNCION DELEGADA, no en `validar()`:
    # `validar()` solo cablea el check (D1), y buscar los nombres ahi seria
    # exigirle logica que este repo se prohibe a proposito.
    cuerpo_del_check = inspect.getsource(
        validate_docs._comprobar_contrato_de_persistencia)
    assert "data-models.md" in cuerpo_del_check and "architecture.md" in cuerpo_del_check, (
        "el contrato se declara en los DOS documentos: el uno dice donde viven los "
        "datos y el otro dice que no siguen al binario, y con uno solo se puede "
        "dejar la mitad sin escribir"
    )
    assert validate_docs.violaciones_del_contrato_de_persistencia("", "vacio"), (
        "un documento vacio no puede declarar el contrato: el predicado tiene que "
        "poder decir 'no' y no solo 'si'"
    )


def test_la_clausula_de_arranque_lista_todas_las_categorias_y_va_en_singular():
    """TASK-068, ronda 2 del Paso 4: el RECUENTO y el PLURAL de la clausula.

    **Los dos supervivientes que este test mata, MEDIDOS el 2026-10-05 (28 046 B,
    `ALL TESTS PASSED`, con los 188 en verde):**

      * `N6_CLAUSULA_SOLO_NOMBRA_LA_PRIMERA` — `', '.join(cats)` -> `', '.join(cats[:1])`
        en `ui/feedback.py::clausula_categorias_arranque`. Con `start_categories`
        de dos elementos el mensaje decia *"(2 categorías: 🟡 Chat y Comunicación)"*:
        **cuenta dos y enseña uno.**
      * `N7_CLAUSULA_PLURAL_ROTO` — `plural = "s" if n != 1 else ""` -> `plural = "s"`.
        Con **una sola** categoria omitida imprimia *"(1 categorías: ...)"*.

    **La causa es una sola y no es de las dos aserciones:** hasta este test
    **ninguno de los 188 montaba un pack con `start_categories` de dos
    elementos**, luego el recuento, el plural y el listado COMPLETO de la
    clausula estaban sin vigilar. Las filas anteriores solo miran una sola
    categoria (`_CAT_ROJO` en T-2, `CATEG_INICIO` en T-3), y con una sola el
    `cats[:1]` es la lista entera y el plural correcto es el de una.

    Por que el recuento lo pide el MOTOR y no el doble: las tres filas entran por
    `PackManagerView.start_pack` de verdad y el recuento de categorias lo pide al
    `ProcessService` real (`_ServicioDeArranque`) con sus barreras y sus ramas de
    omision. Asi "las dos omitidas" es un hecho de T-2 y no un `(0, 2)` puesto a
    mano, y el mutante "arregla el texto y no el motor" no puede pasar.

    **TESTIGOS, y por que estan escritos aqui (ciclo 58).** El parte del ciclo
    nombro el testigo equivocado en tres muertes. Las tres son de filas de
    `test_el_feedback_de_pack_dice_la_verdad` (las linea son las del estado de
    188 y se mueven con cada insercion anterior; el nombre de la fila no se mueve):
      - `T1_TRASPASA` (la lista de apagado colada en la de arranque) muere en la
        **fila 3, "la lista de APAGADO viaja"** (`procs.target_categories == ...`),
        no en la fila 2 como se declaro: la fila 2 mira `procs.categorias` y con el
        traspaso la lista que llega es la que el propio mutante cambio.
      - `T3_CLAUSULA_EN_EXITO_COMPUESTO` (gate + rama `launched > 0` a la vez)
        muere en la **fila 4, "el texto dice la SUMA de los dos recuentos"**
        (`5 iniciadas, 1 con error`, byte a byte), no en la contraprueba.
      - `N2` lo mata la **fila T-2, "la omision tiene que CONTAR como fallo"**
        (`"1 con error" in texto`), no la fila 1 ampliada.
    Ninguna de las tres cambia un veredicto; lo que cambia es que un informe que
    nombra el testigo equivocado se reaudita mal tres ciclos despues.
    """
    print("Testing la clausula de arranque con dos categorias omitidas...")
    import tempfile as _tf_clausula
    from woptimizer.ui.confirmation import AMBAR, VERDE
    from woptimizer.ui.views.pack_manager_view import PackManagerView

    CATEG_A = _CAT_CHAT      # la primera que el pack marco
    CATEG_B = _CAT_SYNC      # la segunda, y la que N6 no nombraba

    class _Arranque:
        """`start_pack_apps` a medida y `start_pack_categories` de VERDAD.

        El doble no inventa el recuento: lo pide al `ProcessService`, con sus
        barreras y sus ramas de omision. `categorias_reales=False` es la unica
        manera de fabricar un `(0, 0)` desde categorias, que es justamente el
        estado que T-2 vuelve inalcanzable y que solo sirve para la fila 3.
        """

        def __init__(self, servicio, arranque_apps=(0, 0), categorias_reales=True):
            self.servicio = servicio
            self.arranque_apps = arranque_apps
            self.categorias_reales = categorias_reales
            self.categorias = None
            self.target = None

        def start_pack_apps(self, apps):
            return self.arranque_apps

        def start_pack_categories(self, cats, targets=None):
            self.categorias = list(cats)
            self.target = list(targets or [])
            if self.categorias_reales:
                return self.servicio.start_pack_categories(cats, targets)
            return 0, 0

    def _toast(paquete, proc):
        """Cruza la puerta REAL y devuelve el par `(texto, color)` publicado."""
        gestor = PackManagerView.__new__(PackManagerView)
        publicado = []
        gestor._cancel_confirm = lambda: None
        gestor.process_service = proc
        gestor.pack_service = None
        gestor.gaming_service = None
        gestor.notification_service = _NotisFalso_()
        gestor.status_label = _EtiquetaFalsa_()
        gestor.after = lambda ms, func=None, *a: func(*a)
        gestor._inline_status = lambda texto, color: publicado.append((texto, color))
        with _HilosSincronos():
            gestor.start_pack(paquete)
        assert len(publicado) == 1, (
            f"la puerta de arranque tiene que publicar UN feedback: {publicado!r}"
        )
        return publicado[0]

    pack_dos = Pack(id="dos", name="Trabajo", apps=[],
                    start_categories=[CATEG_A, CATEG_B])
    pack_una = Pack(id="una", name="Trabajo", apps=[], start_categories=[CATEG_A])

    with _tf_clausula.TemporaryDirectory() as _tmp_clausula:
        # Ningun ejecutable resoluble para ninguna de las dos: las dos se OMITEN
        # por la tercera rama (`process_service.py:949-958`), que las CUENTA una
        # a una. Las dos barreras anteriores no muerden porque ninguna de las dos
        # es roja y el pack no trae `target_categories` en conflicto.
        servicio = _ServicioDeArranque(_tmp_clausula)
        servicio._patrones_de_categoria = lambda cat: []

        # -- fila 1: LAS DOS OMITIDAS. Mata `N6_CLAUSULA_SOLO_NOMBRA_LA_PRIMERA`.
        proc = _Arranque(servicio)
        texto, color = _toast(pack_dos, proc)
        assert proc.categorias == [CATEG_A, CATEG_B], (
            "precondicion: la puerta tiene que ejecutar las DOS categorias del "
            f"pack, y ejecuto {proc.categorias!r}"
        )
        assert color == AMBAR, (
            f"dos categorias marcadas y omitidas no son un exito: {color!r}"
        )
        assert "0 iniciadas, 2 con error" in texto, (
            "las dos omisiones tienen que contar una a una: "
            f"{texto!r}"
        )
        assert CATEG_A in texto and CATEG_B in texto, (
            "la clausula tiene que NOMBRAR LAS DOS categorias que el usuario marco: "
            f"en el mensaje solo sale una de las dos. Texto={texto!r}"
        )
        assert "(2 categorías:" in texto, (
            "el recuento de la clausula tiene que ser el de la lista que se paso: "
            f"dijeron 2 y no {texto!r}"
        )

        # -- fila 2: UNA OMITIDA. Contraprueba de la fila 1, y mata
        #    `N7_CLAUSULA_PLURAL_ROTO`: con el plural fijo en "s" sale
        #    "(1 categorías: ...)".
        texto_una, color_una = _toast(pack_una, _Arranque(servicio))
        assert color_una == AMBAR, f"una categoria omitida tampoco es exito: {color_una!r}"
        assert "(1 categoría: " in texto_una, (
            "una sola categoria se escribe en SINGULAR: con el plural fijo sale "
            f"'(1 categorías: ...)', que es como se leia antes. Texto={texto_una!r}"
        )
        assert "1 con error" in texto_una, (
            f"la categoria omitida tiene que contar como fallo: {texto_una!r}"
        )
        assert CATEG_A in texto_una and CATEG_B not in texto_una, (
            "la clausula nombra lo que el pack marco y solo eso: en un pack de una "
            f"categoria no puede aparecer la otra. Texto={texto_una!r}"
        )

        # -- fila 3: CONTROL NEGATIVO, y sobre el MISMO pack de dos. Sin esta
        #    fila, la clausula podria meterse en la rama de exito y las dos
        #    anteriores seguirian en verde, porque solo probarian que no sale con
        #    UNA categoria (que es lo que mide la contraprueba de T-1).
        texto_ok, color_ok = _toast(
            pack_dos, _Arranque(servicio, arranque_apps=(3, 0), categorias_reales=False))
        assert texto_ok == "🚀 3 apps iniciadas · 'Trabajo'.", (
            "con algo arrancado la clausula NO aparece, byte a byte como el texto "
            f"de siempre: {texto_ok!r}"
        )
        assert color_ok == VERDE, (
            f"el exito real si es verde, que es lo que la degradacion a ambar no "
            f"puede tocar: {color_ok!r}"
        )
    print("La clausula lista, cuenta y habla en singular OK (TASK-068).")


# ---------------------------------------------------------------------------
# TASK-070: `_reparto_de_tests` de `validate_docs.py` no puede re-tokenizar (ni
# re-partir lineas) el `run_tests.py` entero POR CADA SENTENCIA de `__main__`.
#
# MEDIDO el 2026-10-06, no supuesto: `run_tests.py` pesa 1 235 023 B y su
# `__main__` tiene 194 sentencias. `ast.get_source_segment(fuente, stmt)` parte
# las lineas del fichero ENTERO en cada llamada (en 3.13 por `_splitlines_no_ff`;
# OJO: la premisa de la tarea de que "tokeniza" era falsa, pero la conclusion de
# que es O(n^2) en el tamano del fichero era CIERTA, porque partir 194 veces un
# fichero de 1,2 MB son 194 pases completos). Medido aqui: 194 llamadas y
# 7,25 s de los ~13 s del validador entero. El arreglo acordado es partir las
# lineas UNA vez fuera del bucle y recortar por `lineno`/`end_lineno`.
#
# Y hay un segundo hecho, MEDIDO, que decide donde NO optimizar: el marcador
# aparece DOS veces en el fichero. La PRIMERA esta en `_run_tests_sintetico()`,
# que esta POR ENCIMA de `cuerpo_main` (que empieza mas abajo, en el `__main__`).
# El mutante "optimizado" `visto = MARCADOR_HEADLESS in fuente` declara por eso
# `antes = 0` y `desde = <el total entero>` MEDIDO, o sea toda la suite por
# delante del marcador, y EL TOTAL SIGUE DANDO IGUAL, asi que el bug seria
# invisible para cualquier check que solo mire la suma. Por eso estos dos tests
# van ANTES del marcador: el reparto lo deriva el check 7 con
# `ast`, y si el arreglo moviera la frontera, la moverian estos.
# ---------------------------------------------------------------------------


def _reparto_de_tests_via_source_segment(root):
    """IMPLEMENTACION DE REFERENCIA, SOLO DE TEST: el bucle ANTIGUO.

    Copia literal de `_reparto_de_tests` con la UNICA diferencia de la linea que
    TASK-070 cambia: donde el codigo de produccion recorta `lineas[lineno-1:
    end_lineno]`, aqui se llama a `ast.get_source_segment(fuente, stmt)`. Vive
    aqui y no en `validate_docs.py` a proposito: una implementacion de referencia
    que este en el modulo que corrige no corrige nada, se autodeclara buena.

    Devuelve el MISMO 4-tuple `(antes, desde, total, linea_marcador)`. No lleva
    `print()`: la comparesion de tuplas es su unico contrato.
    """
    import validate_docs as vd

    ruta = os.path.join(root, "run_tests.py")
    try:
        with open(ruta, encoding="utf-8") as f:
            fuente = f.read()
    except OSError:
        return None
    try:
        arbol = ast.parse(fuente, filename=ruta)
    except SyntaxError:
        return None
    cuerpo_main = None
    for nodo in arbol.body:
        if (isinstance(nodo, ast.If) and isinstance(nodo.test, ast.Compare)
                and isinstance(nodo.test.left, ast.Name)
                and nodo.test.left.id == "__name__"):
            cuerpo_main = nodo.body
            break
    if cuerpo_main is None:
        return None
    antes = desde = 0
    visto = False
    linea_marcador = None
    for stmt in cuerpo_main:
        llamadas = sum(
            1 for nodo in ast.walk(stmt)
            if isinstance(nodo, ast.Call) and isinstance(nodo.func, ast.Name)
            and nodo.func.id.startswith("test_"))
        if visto:
            desde += llamadas
        else:
            antes += llamadas
        if vd.MARCADOR_HEADLESS in (ast.get_source_segment(fuente, stmt) or ""):
            visto = True
            linea_marcador = stmt.lineno
    if not visto:
        return None
    return (antes, desde, antes + desde, linea_marcador)


def test_el_reparto_de_tests_no_re_tokeniza_por_sentencia():
    """TASK-070 T1: el reparto se deriva SIN re-partir el fichero por sentencia.

    CUENTA INVOCACIONES REALES, no segundos. Un temporizador se rompe en una CI
    mas lenta y mide el host, no el contrato; un conteo de llamadas es exacto y
    no depende de la maquina. Se cuentan las dos puertas por las que se puede
    volver a colar el coste: `ast.get_source_segment` (la de hoy) y
    `tokenize.generate_tokens` (la que la premisa de la tarea daba por buena y
    que en 3.13 no se llama, y tambien por eso cuenta 0 HOY y el assert sigue
    teniendo que exigir 0).

    MEDIDO antes del arreglo: **194** llamadas a `get_source_segment` (una por
    sentencia de `cuerpo_main`), que es el numero que hace fallar este assert.
    MEDIDO despues: **0**. Los dos valores se tomaron sobre el `run_tests.py`
    REAL, porque un fixture sintetico no tiene `_run_tests_sintetico` y por tanto
    solo tiene una ocurrencia del marcador (que es justo lo que hace peligroso al
    mutante que lo busca una vez fuera del bucle; lo mide el otro test).

    Las funciones reales se restauran en un `finally`: un test que deja
    monkeypatched el modulo `ast` poisons el resto de la suite, y en esta suite
    el resto de la suite es justo lo que mide.
    """
    import tokenize
    import validate_docs as vd

    root = os.path.dirname(os.path.abspath(__file__))
    conteo = {"get_source_segment": 0, "generate_tokens": 0}
    reales = (ast.get_source_segment, tokenize.generate_tokens)

    def get_source_segment_contado(*args, **kwargs):
        conteo["get_source_segment"] += 1
        return reales[0](*args, **kwargs)

    def generate_tokens_contado(*args, **kwargs):
        conteo["generate_tokens"] += 1
        return reales[1](*args, **kwargs)

    ast.get_source_segment = get_source_segment_contado
    tokenize.generate_tokens = generate_tokens_contado
    try:
        reparto = vd._reparto_de_tests(root)
    finally:
        ast.get_source_segment = reales[0]
        tokenize.generate_tokens = reales[1]

    assert reparto is not None, (
        "el reparto tiene que derivarse del `run_tests.py` REAL; si sale None el "
        "aserto de conteo de este test no probaria nada, porque un conteo de "
        "llamadas sobre una derivacion que no llega al bucle es 0 sin haber "
        "corregido nada"
    )
    assert conteo["get_source_segment"] == 0, (
        "TASK-070: `_reparto_de_tests` llamo a `ast.get_source_segment` "
        f"{conteo['get_source_segment']} veces (una por sentencia de `__main__`), "
        "y cada llamada parte las lineas del `run_tests.py` entero: eso es "
        "O(n^2) en el tamano del fichero. Las lineas se parten UNA vez, fuera del "
        "bucle, y cada sentencia recorta su tramo con `lineno`/`end_lineno`"
    )
    assert conteo["generate_tokens"] == 0, (
        "TASK-070: `_reparto_de_tests` tokenizo "
        f"{conteo['generate_tokens']} veces. La premisa de la tarea decia que "
        "`get_source_segment` tokeniza el fichero entero; en 3.13 no lo hace "
        "(parte lineas), pero si un dia vuelve a hacerlo por la puerta de "
        "`tokenize`, este conteo lo canta"
    )


def test_el_split_derivado_no_cambia_con_el_arreglo():
    """TASK-070 T2: el reparto derivado NO se mueve con el arreglo.

    Este es el que mata al ARREGLO EQUIVOCADO, no al fallo original: T1 exige que
    el coste desaparezca y T2 exige que el NUMERO sea el de siempre. Sin T2, un
    `visto = MARCADOR_HEADLESS in fuente` pasa el total (191) con todo el reparto
    partido, y el bug sale de la app semanas despues.

    Se comparan las CUATRO componentes, no el total: `(antes, desde, total,
    linea)`. Un reparto movido conserva la suma por construccion -- es sumar lo
    mismo en dos botes distintos --, asi que comparar el total es comparar la
    unica cifra que el bug NO rompe. Y el total solo por si mismo tampoco sirve:
    "el nuevo devuelve 189" lo cumple una funcion rota que devuelve ceros.
    (Las cifras de aqui son las del reparto de ENTRADA, 189; con las dos sondas
    de este ciclo delante del marcador, 191. Lo que T2 exige es que las dos
    derivaciones coincidan, no un literal.)

    La comparacion es de las DOS DERIVACIONES de la MISMA funcion sobre el MISMO
    fichero en la MISMA corrida, que es lo unico que prueba que el arreglo no
    movio nada. La tercera asercion es la que sostiene la potencia del test: exige
    que el fichero REAL siga teniendo **dos** ocurrencias del marcador. Si alguna
    vez se queda con una, el mutante M1 pasaria TODOS los fixtures sinteticos y
    este test dejaria de discriminar sin que nadie lo notase, porque compara dos
    implementaciones que seguirian dando el mismo numero.
    """
    import validate_docs as vd

    root = os.path.dirname(os.path.abspath(__file__))
    nuevo = vd._reparto_de_tests(root)
    viejo = _reparto_de_tests_via_source_segment(root)

    assert viejo is not None, (
        "la implementacion de referencia tiene que derivar el reparto del "
        f"`run_tests.py` REAL: devolvio {viejo!r}. Si esto falla, la comparacion de "
        "abajo no probaria nada porque estaria comparando contra un `None`"
    )
    assert nuevo == viejo, (
        "TASK-070: el reparto derivado cambio con el arreglo. "
        f"Nuevo (lineas) = {nuevo!r}; referencia (`get_source_segment`) = "
        f"{viejo!r}. Las cuatro componentes se comparan porque un reparto movido "
        "deja la suma igual: si el total cuadra y las tres primeras no, el numero "
        "que declara STATUS.md esta contando otra cosa"
    )
    with open(os.path.join(root, "run_tests.py"), encoding="utf-8") as fh:
        fuente = fh.read()
    assert fuente.count(vd.MARCADOR_HEADLESS) >= 2, (
        "TASK-070: el `run_tests.py` REAL tiene que seguir teniendo DOS o mas "
        f"ocurrencias de `{vd.MARCADOR_HEADLESS}` (ahora tiene "
        f"{fuente.count(vd.MARCADOR_HEADLESS)}). La segunda esta en "
        "`_run_tests_sintetico()`, POR ENCIMA de `__main__`, y es la que hace "
        "peligroso buscar el marcador una vez fuera del bucle: con una sola "
        "ocurrencia, el mutante M1 daria el mismo numero y este test, con las dos "
        "implementaciones de acuerdo, pasaria sin discriminar nada"
    )


def test_pack_model_is_protected_strict_bool():
    """TASK-071: Pack.is_protected es un booleano estricto y por defecto es False."""
    print("Testing Pack.is_protected strict bool (TASK-071)...")
    from pydantic import ValidationError
    from woptimizer.models import Pack

    p = Pack(id="test_default", name="Test")
    assert p.is_protected is False, "is_protected debe ser False por defecto"

    p_true = Pack(id="test_true", name="Test", is_protected=True)
    assert p_true.is_protected is True

    p_false = Pack(id="test_false", name="Test", is_protected=False)
    assert p_false.is_protected is False

    for bad_val in ("true", "false", "1", "0", 1, 0, [True], {"val": True}):
        try:
            Pack(id="test_bad", name="Test", is_protected=bad_val)
            assert False, f"Pack no debe aceptar is_protected={bad_val!r} (strict=True)"
        except ValidationError:
            pass


def test_pack_service_ensures_default_protected_pack_and_cannot_delete():
    """TASK-071: PackService asegura DEFAULT_PROTECTED_PACK en memoria y prohibe su borrado."""
    print("Testing PackService protected pack lifecycle and immutability (TASK-071)...")
    import tempfile
    from woptimizer.services.pack_service import PackService, DEFAULT_PROTECTED_PACK

    with tempfile.TemporaryDirectory() as tmpdir:
        json_path = os.path.join(tmpdir, "profiles.json")
        svc = PackService(data_path=json_path)

        prot = svc.get_protected_pack()
        assert prot is not None, "PackService debe asegurar un pack protegido"
        assert prot.id == "protected_apps"
        assert prot.is_protected is True
        assert prot.name == DEFAULT_PROTECTED_PACK.name

        assert svc.get_protected_apps() == set()

        prot.apps.append(r"C:\Program Files\App\Guard.EXE")
        svc._data.packs["protected_apps"] = prot
        svc.invalidate_cache()

        apps = svc.get_protected_apps()
        assert r"c:\program files\app\guard.exe" in apps
        assert "guard.exe" in apps
        assert "guard" in apps

        try:
            svc.delete_pack("protected_apps")
            assert False, "delete_pack('protected_apps') debio lanzar ValueError"
        except ValueError as e:
            assert "protegidas" in str(e).lower()

        user_packs = svc.get_user_packs()
        assert "protected_apps" not in user_packs
        assert not any(p.is_protected for p in user_packs.values())

        assert svc.create_user_pack("protected_apps", "Protegidas", []) is False, (
            "create_user_pack no debe colisionar con pack protegido"
        )


def test_protected_apps_survive_kill_processes_and_gaming_pack():
    """TASK-071: Las apps protegidas no son matadas por kill_processes ni execute_pack."""
    print("Testing protected apps survival in kill_processes and gaming_service (TASK-071)...")
    import tempfile
    from woptimizer.models import ProcessInfo, Pack
    from woptimizer.services.pack_service import PackService
    from woptimizer.services.process_service import ProcessService
    from woptimizer.services.gaming_service import GamingService

    with tempfile.TemporaryDirectory() as tmpdir:
        json_path = os.path.join(tmpdir, "profiles.json")
        pack_svc = PackService(data_path=json_path)

        prot = pack_svc.get_protected_pack()
        prot.apps = ["safe_app.exe", "mybrowser.exe"]
        pack_svc._data.packs["protected_apps"] = prot
        pack_svc.invalidate_cache()

        proc_svc = ProcessService(pack_service=pack_svc)

        p_safe = ProcessInfo(pid=99991, name="safe_app.exe", full_name="safe_app.exe", category="Navegadores", memory_mb=50.0)
        p_other = ProcessInfo(pid=99992, name="other.exe", full_name="other.exe", category="Navegadores", memory_mb=50.0)

        killed, failed, skipped, freed = proc_svc.kill_processes([p_safe, p_other])
        assert skipped >= 1, f"safe_app debio ser skipped, skipped={skipped}"

        gaming_svc = GamingService(process_service=proc_svc, pack_service=pack_svc)

        res = gaming_svc.execute_pack(prot)
        assert res == (0, 0, 0, 0.0), f"execute_pack sobre pack protegido debe ser (0, 0, 0, 0.0), obtenido {res}"

        p_browser = ProcessInfo(pid=99993, name="mybrowser.exe", full_name="mybrowser.exe", category="🟢 Navegadores", memory_mb=100.0)
        test_pack = Pack(id="test_browser_pack", name="Cerrar Navegadores", target_categories=["🟢 Navegadores"], apps=["other.exe"])
        to_kill, count_protected = gaming_svc._seleccion(test_pack, [p_browser, p_other])
        assert p_browser not in to_kill, "mybrowser.exe esta protegido y no debe ser seleccionado para kill"
        assert count_protected >= 1, "count_protected debe contabilizar la app protegida"


